// Dibuat otomatis oleh alat/gabung-tes.js — sunting alat/tes-bagian-*.js lalu jalankan ulang.
// Bank soal Mode Tes: tiap misi punya tujuan pembelajaran, Paket A (tes awal) dan Paket B (tes akhir),
// masing-masing 6 soal berurutan indikator interpretasi → analisis → inferensi → evaluasi → eksplanasi → regulasi.
// opsi[0] adalah kunci; urutan diacak saat ditampilkan.
const TES_MISI = {"perahu":{"tujuan":["Menjelaskan hubungan gaya ke atas dengan volume zat cair yang dipindahkan (Hukum Archimedes).","Menganalisis pengaruh ukuran perahu, bahan, dan massa jenis air terhadap kedalaman celup dan muatan.","Merancang dan mengevaluasi model perahu berdasarkan data uji, kriteria, dan kendala."],"A":[{"ind":"interpretasi","soal":"Tabel uji sebuah perahu: muatan 1 kg → tercelup 2,0 cm; 2 kg → 3,2 cm; 3 kg → 4,4 cm. Tinggi dinding perahu 5 cm. Makna data tersebut adalah …","opsi":["Tiap tambahan 1 kg menambah celup 1,2 cm, sehingga pada 3 kg sisa dindingnya tinggal 0,6 cm.","Perahu makin dalam tercelup karena airnya makin berat, sehingga pada muatan 3 kg perahu pasti sudah tenggelam.","Kedalaman celup naik dua kali lipat setiap muatan dua kali lipat, jadi hubungan keduanya berbanding lurus murni.","Perahu tercelup lebih dangkal saat muatan bertambah, karena gaya ke atas dari air ikut membesar lebih cepat."],"bahas":"Selisih kedalaman tiap 1 kg adalah 1,2 cm (2,0 → 3,2 → 4,4). Pada 3 kg, sisa dinding di atas air 5 − 4,4 = 0,6 cm, masih mengapung tetapi belum memenuhi lambung bebas 2 cm."},{"ind":"analisis","soal":"Rani membuat dua perahu dari bahan yang sama dengan panjang dan tinggi sama. Perahu P lebarnya 15 cm, perahu Q 30 cm. Dengan muatan sama, perahu Q tercelup lebih dangkal. Penyebab paling tepat adalah …","opsi":["Alas perahu Q lebih luas, sehingga air yang sama banyak dapat dipindahkan dengan kedalaman celup lebih kecil.","Perahu Q lebih berat, sehingga gaya ke atas yang diterimanya lebih besar dan perahu terangkat lebih tinggi.","Air di bawah perahu Q lebih rapat karena tertekan alas yang lebar, sehingga massa jenis airnya menjadi lebih besar.","Perahu Q lebih stabil karena lebar, dan perahu yang stabil selalu tercelup lebih dangkal daripada perahu sempit."],"bahas":"Volume air yang dipindahkan = luas alas × kedalaman celup. Untuk berat yang sama, alas yang lebih luas cukup tercelup lebih dangkal."},{"ind":"inferensi","soal":"Perahu yang sama diuji di genangan air hujan (air tawar) dan di air rob (air laut) dengan muatan 3 kg. Dugaan yang paling masuk akal adalah …","opsi":["Di air laut perahu tercelup sedikit lebih dangkal, karena air laut lebih rapat daripada air hujan yang tawar.","Di air laut perahu tercelup lebih dalam, karena garam yang terlarut membuat air lebih berat menekan perahu ke bawah.","Kedalaman celup sama persis di kedua tempat, karena massa perahu dan muatannya sama sekali tidak berubah.","Di air laut perahu lebih cepat bocor, karena garam merusak bahan perahu sehingga gaya ke atasnya berkurang."],"bahas":"Air laut (± 1.025 kg/m³) lebih rapat daripada air tawar (± 1.000 kg/m³). Berat air yang dipindahkan harus sama dengan berat perahu, jadi volume yang dipindahkan di air laut lebih kecil."},{"ind":"evaluasi","soal":"Budi berkata, \"Perahu styrofoam pasti paling bagus karena paling ringan.\" Penilaian yang paling tepat terhadap pendapat Budi adalah …","opsi":["Belum tentu: bahan yang ringan bisa patah dan biayanya harus dihitung, jadi perlu dibandingkan dengan data hasil uji.","Tepat: perahu yang paling ringan selalu memiliki muatan maksimum terbesar, sehingga pasti memenuhi semua kriteria.","Tepat: styrofoam dapat mengapung sendiri, sehingga perahu styrofoam tidak mungkin tenggelam apa pun muatannya.","Kurang tepat: perahu yang ringan selalu mudah terbalik, jadi bahan berat seperti seng pasti lebih baik."],"bahas":"Kriteria perahu meliputi lambung bebas, kekuatan, stabilitas, dan biaya. Ringan hanya satu sifat; klaim \"pasti paling bagus\" harus diuji terhadap semua kriteria."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa perahu dari seng bisa mengapung, padahal seng jauh lebih rapat daripada air, adalah …","opsi":["Bentuk cekungnya memindahkan banyak air, sehingga berat air yang dipindahkan mengimbangi berat perahu.","Seng yang tipis menjadi lebih ringan daripada air, sehingga massa jenis seng berubah menjadi lebih kecil daripada air.","Udara di dalam perahu mendorong perahu ke atas dengan kuat, sehingga perahu terangkat tanpa bantuan air sama sekali.","Permukaan air memiliki tegangan yang kuat, sehingga benda berat seperti seng dapat ditahan di atas permukaannya."],"bahas":"Menurut Hukum Archimedes, gaya ke atas sama dengan berat air yang dipindahkan. Bentuk cekung membuat volume yang dipindahkan besar, walaupun bahannya rapat."},{"ind":"regulasi","soal":"Rancangan pertamamu ternyata tenggelam saat diberi muatan 3 kg. Langkah berikutnya yang paling tepat adalah …","opsi":["Membandingkan kedalaman celup dengan tinggi dinding, lalu mengubah satu ukuran saja dan menguji ulang sekali lagi.","Mengganti bahan, ukuran, dan tinggi dinding sekaligus agar perahu berikutnya pasti mengapung dengan muatan 3 kg.","Mengurangi muatan uji menjadi 1 kg agar perahu tidak tenggelam, lalu menuliskan bahwa rancangan sudah berhasil.","Menyalin ukuran perahu kelompok lain yang berhasil, karena hasil percobaan sendiri tidak perlu dianalisis lagi."],"bahas":"Regulasi diri berarti memeriksa data sendiri dan memperbaiki rancangan secara teratur. Mengubah satu variabel membuat penyebab perubahan hasil bisa diketahui."}],"B":[{"ind":"interpretasi","soal":"Tabel uji: muatan 0 kg → tercelup 0,8 cm; 2 kg → 2,4 cm; 4 kg → 4,0 cm. Tinggi dinding 6 cm, dan syarat lambung bebas minimal 2 cm. Kesimpulan yang tepat adalah …","opsi":["Setiap tambahan 1 kg menambah celup 0,8 cm, sehingga pada 4 kg sisa dinding tepat 2 cm dan masih memenuhi syarat.","Perahu sudah gagal pada muatan 4 kg, karena kedalaman celup 4,0 cm lebih dari setengah tinggi dinding perahu.","Perahu tercelup 0,8 cm tanpa muatan, jadi data itu salah karena perahu kosong seharusnya tidak tercelup sama sekali.","Kedalaman celup naik tiga kali lipat saat muatan naik dua kali lipat, sehingga perahu makin cepat tenggelam."],"bahas":"Kenaikan 1,6 cm tiap 2 kg berarti 0,8 cm per kg. Pada 4 kg, sisa dinding 6 − 4,0 = 2,0 cm, tepat memenuhi syarat. Perahu kosong tercelup karena beratnya sendiri."},{"ind":"analisis","soal":"Dua perahu berukuran sama, satu dari triplek dan satu dari styrofoam, diberi muatan yang sama. Perahu triplek tercelup lebih dalam. Penyebab paling tepat adalah …","opsi":["Perahu triplek lebih berat, sehingga perahu itu perlu memindahkan lebih banyak air untuk mengimbangi seluruh beratnya.","Triplek menyerap air sehingga gaya ke atasnya hilang, sedangkan styrofoam sama sekali tidak menyerap air.","Styrofoam memantulkan tekanan air ke atas, sedangkan triplek meneruskan tekanan air masuk ke dalam perahu.","Perahu triplek lebih kuat, dan perahu yang lebih kuat selalu tercelup lebih dalam karena menahan muatan lebih baik."],"bahas":"Gaya ke atas harus mengimbangi berat perahu ditambah muatan. Perahu yang lebih berat memerlukan gaya ke atas lebih besar, jadi tercelup lebih dalam."},{"ind":"inferensi","soal":"Sebuah perahu membawa 3 kg dengan lambung bebas 1 cm. Jika panjangnya ditambah 50% tanpa mengubah lebar, tinggi, dan bahan, dugaan yang paling masuk akal adalah …","opsi":["Perahu tercelup lebih dangkal karena alasnya lebih luas, sehingga lambung bebasnya bertambah.","Perahu tercelup lebih dalam karena makin panjang, sehingga perahu makin berat dan lambung bebasnya makin kecil.","Lambung bebas tetap 1 cm karena lebar dan tinggi tidak berubah, dan panjang tidak memengaruhi gaya ke atas.","Perahu menjadi tidak stabil dan pasti terbalik, karena perahu yang panjang mudah oleng ke depan dan ke belakang."],"bahas":"Luas alas naik 50%, sedangkan berat perahu hanya naik sedikit karena muatannya tetap. Untuk memindahkan berat air yang hampir sama, kedalaman celup berkurang."},{"ind":"evaluasi","soal":"Kelompok Sinta mengklaim, \"Perahu kami terbaik karena muatan maksimumnya 9 kg.\" Biaya perahu itu Rp 45.000. Penilaian yang paling tepat adalah …","opsi":["Belum terbaik: muatannya memang besar, tetapi biayanya melebihi kendala lomba Rp 30.000 yang sudah ditetapkan.","Tepat: muatan maksimum adalah satu-satunya ukuran perahu terbaik, sehingga biayanya tidak perlu dipertimbangkan.","Tepat: perahu yang mampu membawa tiga kali muatan uji pasti juga stabil dan kuat, sehingga semua kriteria terpenuhi.","Kurang tepat: muatan 9 kg mustahil dicapai oleh model perahu, jadi data kelompok Sinta pasti salah ukur."],"bahas":"Rancangan terbaik harus memenuhi semua kriteria dan kendala. Biaya Rp 45.000 melanggar kendala Rp 30.000, sekuat apa pun perahunya."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa perahu tenggelam ketika muatannya terlalu banyak adalah …","opsi":["Perahu tercelup makin dalam; bila celupnya melebihi tinggi dinding, air masuk dan perahu itu pun tenggelam.","Muatan yang berat membuat massa jenis air di sekitar perahu turun, sehingga gaya ke atas air menjadi lebih kecil.","Muatan menambah tekanan udara di dalam perahu, sehingga udara keluar dan perahu kehilangan daya apungnya.","Setiap perahu punya batas berat yang tetap, dan setelah batas itu terlampaui gaya ke atas air hilang tiba-tiba."],"bahas":"Makin berat muatan, makin banyak air yang harus dipindahkan, jadi perahu tercelup makin dalam. Bila melebihi tinggi dinding, air masuk dan perahu tenggelam."},{"ind":"regulasi","soal":"Perahumu memenuhi semua kriteria, tetapi kamu baru menguji satu kali. Sikap yang paling tepat adalah …","opsi":["Mengulang uji beberapa kali untuk memastikan hasilnya konsisten, baru kemudian menarik kesimpulan akhir dari data ujinya.","Langsung menyimpulkan rancangan berhasil, karena satu kali uji yang sukses sudah cukup untuk membuktikan semuanya.","Menambah muatan sampai perahu tenggelam, lalu melaporkan muatan saat tenggelam sebagai muatan aman perahu.","Mengganti rancangan dengan bentuk baru agar hasilnya lebih baik, walaupun rancangan lama sudah memenuhi kriteria."],"bahas":"Satu hasil bisa kebetulan. Pemikir kritis mengulang uji untuk memastikan hasilnya bisa dipercaya sebelum menarik kesimpulan."}]},"penjernih":{"tujuan":["Menjelaskan prinsip filtrasi dan adsorpsi dalam memisahkan campuran.","Menganalisis pengaruh urutan dan ketebalan lapisan terhadap kejernihan, bau, dan debit air.","Mengevaluasi rancangan penjernih berdasarkan data serta memahami batas penyaringan (tidak membunuh kuman)."],"A":[{"ind":"interpretasi","soal":"Data uji: pasir 4 cm → kekeruhan 60 NTU, debit 150 mL/menit; pasir 8 cm → 30 NTU, 90 mL/menit; pasir 12 cm → 18 NTU, 50 mL/menit. Makna data tersebut adalah …","opsi":["Pasir lebih tebal membuat air lebih jernih, tetapi alirannya makin lambat, jadi tebalnya perlu ditimbang.","Pasir yang lebih tebal membuat air lebih jernih dan alirannya lebih cepat, sehingga pasir setebal mungkin pasti terbaik.","Ketebalan pasir tidak berpengaruh pada kekeruhan, karena yang menjernihkan air hanyalah lapisan arang di bawahnya.","Debit turun karena pasirnya kotor, sehingga pasir harus dicuci dulu sebelum data ini dapat dipakai untuk menyimpulkan."],"bahas":"Kekeruhan turun (60 → 30 → 18 NTU) tetapi debit juga turun (150 → 90 → 50 mL/menit). Ada tarik-menarik antara kejernihan dan kecepatan aliran."},{"ind":"analisis","soal":"Doni menaruh pasir halus di lapisan paling atas dan kerikil di paling bawah. Setelah beberapa menit, aliran air hampir berhenti. Penyebab paling tepat adalah …","opsi":["Kotoran kasar langsung menyumbat celah kecil pasir di atas, karena tidak ada lapisan kasar yang menahannya.","Kerikil di bawah terlalu berat sehingga menekan pasir di atasnya menjadi padat, akibatnya air tidak dapat lewat.","Pasir halus menyerap air seperti spons, sehingga air tertahan di dalam pasir dan tidak keluar dari botol.","Kerikil di bawah mendinginkan air yang lewat, dan air yang dingin selalu lebih sulit mengalir daripada air hangat."],"bahas":"Lapisan kasar di atas berfungsi menahan kotoran besar. Tanpa itu, kotoran kasar langsung menutup celah kecil pasir halus sehingga aliran tersumbat."},{"ind":"inferensi","soal":"Air hasil saringan sudah jernih (15 NTU), tetapi masih sedikit berbau. Lapisan yang paling mungkin perlu ditambah atau dipertebal adalah …","opsi":["Arang, karena pori-porinya yang sangat banyak menyerap zat penyebab bau yang lolos dari lapisan pasir halus.","Kerikil, karena celahnya yang besar menahan partikel bau sebelum masuk ke lapisan pasir yang lebih halus.","Ijuk, karena serat ijuk yang panjang mengikat bau sehingga air yang keluar menjadi segar dan tidak berbau.","Pasir, karena pasir yang lebih tebal menahan partikel bau seperti ia menahan partikel penyebab kekeruhan."],"bahas":"Zat penyebab bau berukuran sangat kecil dan larut, sehingga tidak tertahan oleh celah penyaring. Arang menyerapnya melalui adsorpsi pada pori-porinya."},{"ind":"evaluasi","soal":"Seorang warga berkata, \"Airnya sudah jernih, berarti aman diminum.\" Penilaian yang paling tepat terhadap pendapat itu adalah …","opsi":["Kurang tepat: penyaringan tidak membunuh kuman, jadi air tetap harus direbus sampai mendidih sebelum diminum warga.","Tepat: air yang jernih berarti semua kotoran sudah tertahan, termasuk kuman yang ukurannya juga sangat kecil.","Tepat: lapisan arang membunuh kuman di dalam air, sehingga air yang sudah melewati arang pasti aman diminum.","Kurang tepat: air saringan tidak boleh dipakai sama sekali, bahkan untuk mencuci, karena masih mengandung pasir."],"bahas":"Jernih tidak sama dengan bebas kuman. Kuman jauh lebih kecil daripada celah pasir dan tidak mati oleh arang, jadi air harus direbus sampai mendidih."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa urutan lapisan kerikil–ijuk–pasir–arang (dari atas ke bawah) bekerja dengan baik adalah …","opsi":["Lapisan kasar menahan kotoran besar agar pasir tidak tersumbat; pasir menahan partikel halus, arang menyerap bau.","Lapisan disusun dari yang paling ringan ke yang paling berat, sehingga lapisan tidak tercampur saat air dituangkan.","Air harus melewati lapisan paling mahal di bagian akhir, agar bahan yang paling bagus tidak cepat rusak oleh kotoran.","Urutan lapisan sebenarnya tidak penting, asalkan semua bahan ada di dalam botol, karena air tetap melewati semuanya."],"bahas":"Penyaringan bertahap dari celah besar ke kecil mencegah penyumbatan dini, lalu arang bekerja pada zat terlarut penyebab bau."},{"ind":"regulasi","soal":"Hasil penyaringanmu ternyata jauh lebih keruh daripada prediksimu. Langkah yang paling tepat adalah …","opsi":["Memeriksa urutan dan ketebalan lapisan, lalu menguji ulang dengan mengubah satu hal saja setiap kali menguji.","Menyimpulkan bahwa air sungai memang tidak dapat dijernihkan, sehingga percobaan tidak perlu dilanjutkan lagi.","Menuangkan air yang lebih jernih dari tempat lain agar hasilnya sesuai dengan prediksi yang sudah dibuat.","Mengganti semua lapisan dan menambah penyaringan sekaligus, agar hasil berikutnya pasti jauh lebih jernih."],"bahas":"Perbedaan antara prediksi dan hasil adalah petunjuk. Memeriksa rancangan lalu mengubah satu hal membantu menemukan penyebabnya."}],"B":[{"ind":"interpretasi","soal":"Data uji: penyaringan 1 kali → 40 NTU; 2 kali → 22 NTU; 3 kali → 18 NTU. Makna data yang paling tepat adalah …","opsi":["Mengulang penyaringan membuat air makin jernih, tetapi tambahannya makin kecil, terutama dari kali kedua ke kali ketiga.","Setiap penyaringan menurunkan kekeruhan dengan jumlah yang sama, sehingga penyaringan keempat akan menghasilkan air bening.","Penyaringan ketiga tidak berguna sama sekali, karena kekeruhannya sama persis dengan hasil penyaringan kedua.","Kekeruhan turun karena air didiamkan lebih lama, bukan karena penyaringan diulang beberapa kali oleh kelompok."],"bahas":"Penurunan pertama 18 NTU (40 → 22), penurunan kedua hanya 4 NTU (22 → 18). Manfaat pengulangan makin kecil."},{"ind":"analisis","soal":"Dua penjernih memakai lapisan yang sama, tetapi penjernih P tanpa arang dan penjernih Q dengan arang 5 cm. Kekeruhannya hampir sama, tetapi air Q tidak berbau. Kesimpulan yang tepat adalah …","opsi":["Arang terutama menghilangkan bau, sedangkan kejernihan air lebih banyak ditentukan oleh lapisan pasir halus di atasnya.","Arang terutama berperan menjernihkan air, sehingga penjernih P seharusnya jauh lebih keruh daripada penjernih Q.","Arang membuat air lebih cepat mengalir, sehingga bau keluar bersama air dan tidak tertinggal di dalam botol.","Perbedaan bau terjadi karena air Q lebih dingin, dan air yang dingin tidak mengeluarkan bau sama sekali."],"bahas":"Karena hanya arang yang berbeda, perbedaan hasil (bau) dapat dikaitkan dengan arang. Kekeruhan yang sama menunjukkan arang bukan penentu utama kejernihan."},{"ind":"inferensi","soal":"Debit penjernihmu hanya 20 mL/menit, padahal syaratnya minimal 60 mL/menit. Dugaan penyebab yang paling masuk akal adalah …","opsi":["Lapisan pasir halus terlalu tebal, sehingga celahnya yang kecil memperlambat aliran air.","Lapisan kerikil terlalu tipis, karena kerikil berfungsi mendorong air agar mengalir lebih cepat ke bawah.","Botolnya terlalu besar, sehingga air memerlukan waktu lebih lama untuk mengisi seluruh ruang di dalamnya.","Arang menyerap terlalu banyak air, sehingga hanya sedikit air yang tersisa untuk keluar dari dalam botol."],"bahas":"Celah pasir halus sangat kecil sehingga memperlambat aliran. Makin tebal lapisan pasir, makin panjang jalur sempit yang harus dilewati air."},{"ind":"evaluasi","soal":"Kelompok Ani mengklaim penjernihnya terbaik karena airnya paling jernih (5 NTU), padahal debitnya 15 mL/menit. Penilaian yang paling tepat adalah …","opsi":["Belum terbaik: airnya memang sangat jernih, tetapi debitnya jauh di bawah syarat minimal 60 mL/menit yang diminta.","Tepat: kejernihan adalah tujuan utama penjernih, sehingga debit yang lambat sama sekali tidak perlu dipertimbangkan.","Tepat: air yang mengalir lambat selalu lebih jernih, sehingga debit kecil justru tanda penjernih bekerja dengan baik.","Kurang tepat: kekeruhan 5 NTU mustahil dicapai penjernih sederhana, jadi alat ukur kelompok Ani pasti rusak."],"bahas":"Rancangan harus memenuhi semua kriteria. Kejernihan tinggi dengan debit sangat lambat belum memenuhi kebutuhan warga."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa arang dapat menghilangkan bau pada air adalah …","opsi":["Pori arang yang sangat banyak membuat zat penyebab bau menempel (teradsorpsi) di seluruh permukaan arang.","Arang bereaksi dengan zat penyebab bau dan mengubahnya menjadi air bersih, seperti reaksi kimia pembakaran.","Arang berwarna hitam sehingga menyerap cahaya, dan cahaya yang terserap itu menghancurkan zat penyebab bau.","Arang lebih berat daripada air, sehingga zat penyebab bau ikut tenggelam bersama arang ke dasar botol."],"bahas":"Adsorpsi adalah menempelnya zat pada permukaan. Pori arang membuat luas permukaannya sangat besar sehingga banyak zat penyebab bau tertangkap."},{"ind":"regulasi","soal":"Setelah menyusun penjernih, kamu sadar belum mencatat ketebalan tiap lapisan. Langkah yang paling tepat adalah …","opsi":["Mengukur dan mencatat ketebalan tiap lapisan lebih dulu, agar hasilnya bisa dibandingkan dan diulang orang lain.","Melanjutkan uji tanpa mencatat, karena yang penting hasil akhirnya jernih dan tidak berbau sama sekali.","Menuliskan ketebalan perkiraan yang paling masuk akal, karena tidak ada orang yang akan memeriksanya lagi.","Membongkar dan membuang penjernih itu, lalu memulai rancangan yang sama sekali baru dari awal lagi."],"bahas":"Data yang tercatat membuat percobaan bisa diperiksa, dibandingkan, dan diulang. Itu bagian dari kejujuran ilmiah."}]},"pendingin":{"tujuan":["Menjelaskan perpindahan kalor secara konduksi, konveksi, dan radiasi.","Menganalisis pengaruh bahan, tebal dinding, warna, dan tutup terhadap lama es bertahan.","Mengevaluasi rancangan kotak pendingin berdasarkan data, kriteria, dan kendala."],"A":[{"ind":"interpretasi","soal":"Data uji: dinding styrofoam 2 cm → es bertahan 8 jam; 4 cm → 14 jam; 6 cm → 19 jam. Makna data yang tepat adalah …","opsi":["Makin tebal dinding styrofoam, makin lama es bertahan, karena kalor yang masuk makin sedikit.","Makin tebal dinding, makin cepat es mencair, karena dinding yang tebal menyimpan lebih banyak panas di dalamnya.","Lama es bertahan selalu naik tepat dua kali lipat setiap tebal dinding dinaikkan menjadi dua kali lipat.","Ketebalan tidak berpengaruh, karena perbedaan lama es bertahan hanya disebabkan suhu udara yang berubah-ubah."],"bahas":"Data naik dari 8 ke 14 ke 19 jam. Dinding lebih tebal memperlambat konduksi kalor, tetapi kenaikannya tidak tepat dua kali lipat."},{"ind":"analisis","soal":"Dua kotak identik diuji bersama, satu tutupnya rapat dan satu ada celah. Es di kotak bercelah habis lebih cepat. Penyebab utamanya adalah …","opsi":["Konveksi: udara panas dari luar masuk dan udara dingin di dalam keluar melalui celah kecil pada tutup kotak.","Radiasi: cahaya matahari masuk lewat celah dan langsung mencairkan es yang berada tepat di bawah celah itu.","Konduksi: celah membuat dinding kotak menjadi lebih tipis, sehingga kalor merambat lebih cepat melalui dinding.","Celah membuat tekanan udara di dalam kotak turun, dan es selalu lebih mudah mencair pada tekanan udara rendah."],"bahas":"Celah memungkinkan aliran udara. Udara panas dari luar membawa kalor masuk; inilah perpindahan kalor secara konveksi."},{"ind":"inferensi","soal":"Kotak berwarna hitam dan kotak berwarna putih yang identik dijemur di dek kapal pada siang hari. Dugaan yang paling masuk akal adalah …","opsi":["Es di kotak hitam lebih cepat habis, karena permukaan hitam menyerap lebih banyak radiasi dari sinar matahari.","Es di kotak putih lebih cepat habis, karena warna putih memantulkan dingin dari es sehingga keluar meninggalkan kotak.","Es di kedua kotak habis bersamaan, karena warna hanya memengaruhi tampilan kotak dan tidak memengaruhi kalor.","Es di kotak hitam lebih lama bertahan, karena warna gelap menahan dingin di dalam kotak dengan lebih baik."],"bahas":"Permukaan gelap menyerap radiasi lebih banyak, sedangkan permukaan putih memantulkannya. Kalor yang terserap kotak hitam mempercepat pencairan es."},{"ind":"evaluasi","soal":"Seorang nelayan berkata, \"Pakai saja kotak papan kayu tebal 8 cm, pasti esnya awet.\" Kotak itu bermassa 9 kg. Penilaian yang paling tepat adalah …","opsi":["Belum tepat: esnya mungkin awet, tetapi massa 9 kg melebihi batas 5 kg sehingga kotak sulit diangkat oleh para nelayan.","Tepat: kayu adalah isolator terbaik, sehingga kotak kayu yang tebal pasti memenuhi semua kriteria yang diminta.","Tepat: kotak yang berat lebih stabil di atas kapal, sehingga massa yang besar justru menjadi keunggulan kotak itu.","Kurang tepat: kayu menghantarkan kalor lebih baik daripada logam, jadi es di kotak kayu pasti cepat habis."],"bahas":"Rancangan harus memenuhi semua kriteria, termasuk massa kotak paling berat 5 kg agar mudah diangkat nelayan."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa styrofoam baik untuk dinding kotak pendingin adalah …","opsi":["Rongga udara di dalam styrofoam menghantarkan kalor dengan sangat buruk, sehingga kalor sulit masuk.","Styrofoam mengandung zat pendingin di dalamnya, sehingga ia ikut mendinginkan udara yang ada di dalam kotak.","Styrofoam berwarna putih, dan warna putih adalah satu-satunya penyebab es dapat bertahan lama di dalam kotak.","Styrofoam memantulkan dingin kembali ke dalam kotak, sehingga dingin dari es tidak keluar ke udara luar."],"bahas":"Udara yang terperangkap adalah penghantar kalor yang buruk (isolator). Karena itu konduksi kalor melalui styrofoam sangat lambat."},{"ind":"regulasi","soal":"Kotakmu hanya membuat es bertahan 9 jam, padahal prediksimu 15 jam. Langkah yang paling tepat adalah …","opsi":["Mencari penyebab perbedaan, misalnya celah di tutup, lalu mengubah satu faktor saja dan menguji ulang.","Mengganti prediksi menjadi 9 jam agar sesuai dengan hasil, lalu menganggap rancangan sudah berhasil.","Menambah es sebanyak mungkin tanpa memeriksa penyebabnya, karena es yang banyak pasti lebih lama habis.","Menyimpulkan bahwa alat ukurnya rusak, karena prediksi yang sudah dipikirkan matang seharusnya benar."],"bahas":"Selisih antara prediksi dan hasil adalah bahan belajar. Mencari penyebab dan menguji ulang secara teratur adalah wujud regulasi diri."}],"B":[{"ind":"interpretasi","soal":"Data uji pada suhu luar berbeda: 26 °C → es bertahan 18 jam; 30 °C → 14 jam; 34 °C → 11 jam. Makna data yang tepat adalah …","opsi":["Makin panas udara luar, makin cepat es habis, karena kalor mengalir lebih cepat masuk ke dalam kotak itu.","Makin panas udara luar, makin lama es bertahan, karena udara panas membuat dinding kotak mengembang dan rapat.","Suhu luar tidak berpengaruh karena kotaknya sama, dan perbedaan hasil hanya terjadi karena kesalahan pengukuran.","Es bertahan berkurang tepat 4 jam setiap suhu naik 4 °C, sehingga pada 38 °C es pasti bertahan 7 jam."],"bahas":"Lama es bertahan turun (18 → 14 → 11 jam) saat suhu luar naik. Penurunannya 4 jam lalu 3 jam, jadi tidak tepat 4 jam setiap kali."},{"ind":"analisis","soal":"Kotak sekam padi dan kotak kardus berlapis dengan tebal dinding sama diuji bersama. Es di kotak sekam bertahan lebih lama. Penyebab yang paling tepat adalah …","opsi":["Sekam padi banyak mengandung rongga udara, sehingga daya hantar kalornya lebih kecil daripada kardus yang berlapis.","Sekam padi lebih berat, dan benda yang lebih berat selalu menahan kalor lebih baik daripada benda yang ringan.","Sekam padi menyerap air lelehan es, sehingga es tetap kering dan tidak mencair walaupun kalor terus masuk.","Kardus berwarna cokelat, sehingga kotak kardus lebih banyak menyerap radiasi daripada kotak dari sekam padi."],"bahas":"Bahan dengan banyak rongga udara menghantarkan kalor lebih buruk. Karena tebal dinding sama, perbedaannya terletak pada daya hantar bahan."},{"ind":"inferensi","soal":"Kotak berisi 3 kg es bertahan 12 jam. Jika es ditambah menjadi 6 kg tanpa mengubah kotak, dugaan yang paling masuk akal adalah …","opsi":["Es bertahan hampir dua kali lebih lama, karena kalor yang dibutuhkan juga dua kali lipat.","Es bertahan lebih singkat, karena es yang banyak membuat kotak lebih penuh sehingga kalor lebih mudah masuk.","Lama es bertahan tetap 12 jam, karena kemampuan kotak menahan kalor sama sekali tidak berubah.","Es bertahan tepat empat kali lebih lama, karena massa es dua kali lipat membuat suhu dalam kotak turun dua kali."],"bahas":"Kalor untuk mencairkan es Q = m × L. Massa dua kali lipat memerlukan kalor dua kali lipat, sedangkan laju kalor masuk hampir sama."},{"ind":"evaluasi","soal":"Kelompok Rio mengklaim kotaknya terbaik karena es bertahan 30 jam, padahal biayanya Rp 95.000. Penilaian yang paling tepat adalah …","opsi":["Belum terbaik: esnya memang sangat awet, tetapi biaya pembuatan Rp 95.000 jauh melebihi batas biaya Rp 60.000.","Tepat: lama es bertahan adalah satu-satunya ukuran kotak terbaik, sehingga biayanya tidak perlu dipertimbangkan.","Tepat: kotak yang mahal pasti memakai bahan terbaik, sehingga hasilnya selalu lebih baik daripada kotak murah.","Kurang tepat: es tidak mungkin bertahan 30 jam di kotak apa pun, sehingga data kelompok Rio pasti keliru."],"bahas":"Rancangan yang baik memenuhi kriteria sekaligus kendala. Biaya Rp 95.000 melanggar kendala Rp 60.000 yang harus dijangkau nelayan."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa es di dalam kotak tetap mencair walaupun tutupnya rapat adalah …","opsi":["Kalor tetap merambat masuk melalui dinding kotak; isolator hanya memperlambat, tidak menghentikannya sama sekali.","Es menghasilkan panasnya sendiri dari dalam, sehingga es tetap mencair walaupun tidak ada kalor yang masuk.","Udara di dalam kotak tertutup lama-lama menjadi panas sendiri, karena udara yang terkurung selalu memanas.","Dingin dari es merambat keluar menembus dinding, sehingga es kehilangan dinginnya lalu berubah menjadi air."],"bahas":"Kalor selalu berpindah dari suhu tinggi ke suhu rendah. Isolator mengurangi laju konduksi, tetapi kalor tetap masuk sedikit demi sedikit."},{"ind":"regulasi","soal":"Kamu mengubah bahan dinding dan warna kotak sekaligus, lalu es bertahan lebih lama. Sikap yang paling tepat adalah …","opsi":["Menguji ulang dengan mengubah satu faktor saja, karena penyebab perbaikan hasilnya belum dapat dipastikan.","Menyimpulkan bahwa bahan dinding yang baru adalah penyebabnya, karena bahan lebih penting daripada warna.","Menyimpulkan bahwa keduanya sama-sama berpengaruh besar, karena hasilnya membaik setelah keduanya diubah.","Tidak perlu memikirkan penyebabnya, karena yang penting kotak baru sudah lebih baik daripada kotak lama."],"bahas":"Bila dua variabel diubah bersamaan, penyebab perubahan hasil tidak dapat dipastikan. Uji adil hanya mengubah satu variabel."}]},"hidroponik":{"tujuan":["Menjelaskan proses fotosintesis dan faktor-faktor yang memengaruhinya.","Menganalisis faktor pembatas (cahaya, CO₂, suhu, dan nutrisi) terhadap pertumbuhan tanaman.","Merancang pengaturan kebun hidroponik yang efektif dan hemat energi berdasarkan data."],"A":[{"ind":"interpretasi","soal":"Data uji pada CO₂ rendah: lampu 40% → massa sawi 70 g; 60% → 95 g; 80% → 98 g; 100% → 99 g. Makna data yang tepat adalah …","opsi":["Cahaya menaikkan massa sampai 60%, lalu hampir tidak berpengaruh karena ada faktor lain yang membatasi.","Massa sawi selalu naik sebanding dengan intensitas lampu, sehingga lampu 100% pasti memberikan hasil terbaik.","Lampu di atas 60% merusak daun, sehingga massa sawi seharusnya turun ketika lampu dinaikkan lebih tinggi lagi.","Intensitas lampu tidak berpengaruh pada massa sawi, karena perbedaan hasil hanya disebabkan kesalahan menimbang."],"bahas":"Kenaikan dari 40% ke 60% menambah 25 g, sedangkan dari 60% ke 100% hanya 4 g. Setelah titik tertentu, cahaya bukan lagi faktor yang membatasi."},{"ind":"analisis","soal":"Faiz menaikkan lampu dari 60% ke 100%, tetapi massa sawi hampir tidak bertambah. Kadar CO₂ ruangan rendah (250 ppm). Penjelasan yang paling tepat adalah …","opsi":["CO₂ menjadi faktor pembatas, sehingga tambahan cahaya tidak termanfaatkan sampai kadar CO₂-nya dinaikkan.","Lampu yang terlalu terang membuat tumbuhan berhenti berfotosintesis untuk melindungi diri dari cahaya.","Sawi sudah mencapai massa maksimumnya, sehingga tidak ada pengaturan apa pun yang dapat menambah massanya.","Cahaya lampu LED tidak dapat dipakai untuk fotosintesis, sehingga hanya cahaya matahari yang berpengaruh."],"bahas":"Menurut prinsip faktor pembatas, laju fotosintesis ditentukan oleh faktor yang paling kurang. Bila CO₂ kurang, menambah cahaya tidak banyak membantu."},{"ind":"inferensi","soal":"Tiga kebun diberi lampu LED berwarna berbeda dengan intensitas sama: merah+biru, putih, dan hijau. Dugaan yang paling masuk akal adalah …","opsi":["Sawi di bawah lampu hijau tumbuh paling lambat, karena klorofil memantulkan sebagian besar cahaya hijau.","Sawi di bawah lampu hijau tumbuh paling cepat, karena daun sawi berwarna hijau sehingga paling cocok dengan cahaya hijau.","Ketiganya tumbuh sama cepat, karena warna cahaya tidak memengaruhi fotosintesis selama intensitasnya sama.","Sawi di bawah lampu putih tumbuh paling lambat, karena cahaya putih sama sekali tidak mengandung warna."],"bahas":"Daun tampak hijau justru karena memantulkan cahaya hijau. Klorofil paling banyak menyerap cahaya merah dan biru."},{"ind":"evaluasi","soal":"Rina berkata, \"Nutrisi AB mix makin pekat makin bagus, jadi pakai 2.000 ppm saja.\" Penilaian yang paling tepat adalah …","opsi":["Kurang tepat: larutan yang terlalu pekat justru menarik air keluar dari akar, sehingga daun sawi akhirnya menjadi layu.","Tepat: tanaman selalu membutuhkan nutrisi sebanyak mungkin, sehingga kadar tertinggi pasti memberi hasil terbaik.","Tepat: nutrisi yang pekat mempercepat fotosintesis, sehingga lampu bisa dimatikan untuk menghemat listrik.","Kurang tepat: tanaman hidroponik tidak membutuhkan nutrisi, karena semua makanannya berasal dari fotosintesis."],"bahas":"Nutrisi diperlukan, tetapi larutan yang terlalu pekat membuat air berpindah keluar dari akar. Klaim \"makin banyak makin bagus\" perlu diuji dengan data."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa lampu dibutuhkan agar sawi di dalam ruangan bertambah massanya adalah …","opsi":["Cahaya memberi energi bagi klorofil untuk membuat glukosa dari CO₂ dan air, bahan tubuh tanaman.","Lampu menghangatkan ruangan, dan kehangatan itulah satu-satunya hal yang membuat sawi tumbuh lebih besar.","Cahaya lampu diserap akar bersama air, lalu disimpan di daun sebagai makanan cadangan bagi tanaman.","Lampu membuat tanaman menghasilkan CO₂ lebih banyak, dan CO₂ itulah yang membuat massa sawi bertambah."],"bahas":"Fotosintesis: 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ dengan energi cahaya. Glukosa menjadi bahan pembangun dan sumber energi tanaman."},{"ind":"regulasi","soal":"Pengaturanmu menghasilkan sawi 120 g, tetapi biaya listriknya Rp 22.000. Langkah yang paling tepat adalah …","opsi":["Mencari pengaturan yang lebih hemat, misalnya lama penyinaran, lalu menguji lagi biaya listriknya.","Melaporkan pengaturan itu sebagai yang terbaik, karena massa sawinya sudah melebihi target 100 g.","Mematikan lampu sama sekali agar biaya listrik nol, walaupun sawi mungkin tidak tumbuh dengan baik.","Mengubah semua pengaturan sekaligus secara acak sampai menemukan biaya listrik di bawah Rp 15.000."],"bahas":"Hasil yang melebihi target belum cukup bila kendala biaya dilanggar. Memperbaiki rancangan secara terarah adalah wujud regulasi diri."}],"B":[{"ind":"interpretasi","soal":"Data uji suhu ruang: 15 °C → massa sawi 55 g; 25 °C → 105 g; 35 °C → 80 g; 40 °C → 30 g. Makna data yang tepat adalah …","opsi":["Suhu terbaik sekitar 25 °C; terlalu dingin fotosintesis lambat, terlalu panas enzimnya pun menjadi rusak.","Makin panas ruangan, makin besar massa sawi, sehingga suhu 40 °C seharusnya memberi hasil yang paling baik.","Suhu tidak berpengaruh pada sawi, karena tanaman hidroponik tidak tumbuh di dalam tanah yang bisa panas.","Makin dingin ruangan, makin besar massa sawi, karena air nutrisi lebih mudah diserap pada suhu yang rendah."],"bahas":"Massa naik lalu turun, dengan puncak sekitar 25 °C. Pola ini menunjukkan suhu optimum bagi kerja enzim fotosintesis."},{"ind":"analisis","soal":"Dua kebun sama-sama memakai lampu 80% selama 14 jam, tetapi kebun A pada CO₂ 250 ppm dan kebun B pada 800 ppm. Kebun B jauh lebih baik. Kesimpulan yang tepat adalah …","opsi":["CO₂ membatasi fotosintesis di kebun A, sehingga cahaya yang sama tidak dapat dimanfaatkan secara penuh oleh sawi.","Kebun B lebih baik karena CO₂ membuat ruangan lebih hangat, dan kehangatan adalah faktor terpenting bagi sawi.","CO₂ adalah makanan langsung bagi akar, sehingga makin banyak CO₂ makin cepat akar menyerap nutrisi.","Perbedaan hasil hanya kebetulan, karena kebun dengan lampu dan lama penyinaran sama pasti hasilnya sama."],"bahas":"Hanya kadar CO₂ yang berbeda, sehingga perbedaan hasil dapat dikaitkan dengan CO₂. CO₂ adalah bahan baku fotosintesis yang diserap daun."},{"ind":"inferensi","soal":"Sawi hanya diberi air tanpa nutrisi (0 ppm), sedangkan cahaya, CO₂, dan suhu sudah ideal. Dugaan yang paling masuk akal adalah …","opsi":["Sawi tumbuh kerdil, karena tanaman tetap memerlukan unsur hara untuk membentuk tubuhnya.","Sawi tumbuh paling besar, karena air murni membuat akar menyerap lebih cepat daripada larutan nutrisi.","Sawi tumbuh normal, karena semua kebutuhan tanaman sudah dipenuhi oleh cahaya dan CO₂ dari udara.","Sawi langsung mati dalam satu hari, karena tanaman sama sekali tidak bisa bertahan tanpa nutrisi."],"bahas":"Fotosintesis menghasilkan glukosa, tetapi tanaman juga memerlukan unsur hara seperti nitrogen untuk membentuk protein dan klorofil."},{"ind":"evaluasi","soal":"Kelompok Dewi mengklaim, \"Lampu 20 jam per hari pasti terbaik karena fotosintesisnya paling lama.\" Biaya listriknya Rp 31.500. Penilaian yang paling tepat adalah …","opsi":["Belum tepat: fotosintesisnya memang lebih lama, tetapi biaya listriknya jauh melebihi batas kendala Rp 15.000.","Tepat: makin lama lampu menyala makin besar massa sawi, sehingga pengaturan 20 jam pasti memenuhi semua syarat.","Tepat: biaya listrik tidak termasuk kriteria tanaman, sehingga yang perlu dinilai hanyalah massa sawinya.","Kurang tepat: tanaman tidak berfotosintesis lebih dari 12 jam sehari, sehingga lampu 20 jam tidak berguna."],"bahas":"Lampu 50 W selama 20 jam × 21 hari = 21 kWh, atau Rp 31.500. Rancangan harus memenuhi kendala biaya Rp 15.000."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa lampu LED merah+biru lebih efisien untuk kebun hidroponik adalah …","opsi":["Klorofil paling banyak menyerap cahaya merah dan biru, sehingga hanya sedikit cahaya lampu yang terbuang.","Cahaya merah dan biru lebih panas, dan panas itulah yang paling dibutuhkan sawi agar cepat tumbuh besar.","Lampu merah dan biru lebih terang daripada lampu putih, sehingga tanaman menerima cahaya yang paling banyak.","Cahaya merah dan biru mengusir hama tanaman, sehingga sawi tumbuh tanpa gangguan dan menjadi lebih besar."],"bahas":"Cahaya yang tidak diserap klorofil, seperti hijau, terbuang. Lampu merah+biru memberikan warna yang paling banyak diserap."},{"ind":"regulasi","soal":"Kamu menemukan pengaturan yang memenuhi semua kriteria setelah 8 kali uji secara acak. Sikap yang paling tepat adalah …","opsi":["Meninjau ulang data untuk memahami faktor yang paling berpengaruh, agar keberhasilan itu bisa dijelaskan dan diulang.","Langsung melaporkan pengaturan itu, karena yang penting hasilnya sudah memenuhi semua kriteria yang ada.","Terus mencoba pengaturan acak lainnya, karena mungkin masih ada yang lebih baik tanpa perlu menganalisis data.","Menghapus data uji yang gagal agar laporan terlihat rapi dan hanya berisi hasil uji yang berhasil saja."],"bahas":"Keberhasilan yang tidak dipahami sulit diulang. Merefleksikan data membantu memahami penyebab keberhasilan."}]},"roket":{"tujuan":["Membedakan perubahan fisika dan perubahan kimia berdasarkan terbentuknya zat baru.","Menganalisis reaksi cuka dan soda kue, termasuk pereaksi pembatas dan gas yang dihasilkan.","Merancang roket yang hemat bahan dan aman berdasarkan data uji serta kriteria dan kendala."],"A":[{"ind":"interpretasi","soal":"Data uji dengan soda kue 20 g: cuka 100 mL → gas 2,0 L; 200 mL → 4,0 L; 300 mL → 5,7 L; 400 mL → 5,7 L. Makna data yang tepat adalah …","opsi":["Gas bertambah sampai cuka sekitar 300 mL, lalu tetap karena soda kue sudah habis (pereaksi pembatas).","Gas selalu bertambah sebanding dengan cuka, sehingga cuka 400 mL seharusnya menghasilkan gas sekitar 8 L.","Cuka di atas 300 mL menghentikan reaksi, karena cuka yang terlalu banyak menetralkan gas yang sudah terbentuk.","Gas tetap pada 5,7 L karena botolnya sudah penuh, sehingga gas tambahan keluar lewat celah sumbat botol."],"bahas":"Soda kue 20 g hanya dapat menghasilkan gas sekitar 5,7 L. Setelah soda kue habis, menambah cuka tidak menambah gas; cuka yang berlebih terbuang."},{"ind":"analisis","soal":"Dua roket memakai bahan yang sama, tetapi soda kue roket A dituang langsung dan roket B dibungkus tisu. Busa roket A meluap sebelum botol tertutup. Penyebab paling tepat adalah …","opsi":["Tanpa bungkus, gas langsung terbentuk sebelum sumbat terpasang, sedangkan tisu menunda reaksi beberapa detik.","Tisu menambah jumlah gas yang terbentuk, sehingga roket B mampu menahan busanya tetap berada di dalam botol.","Soda kue yang dituang langsung lebih banyak larut, sehingga zat baru tidak terbentuk dan hanya busa yang muncul.","Busa pada roket A berasal dari udara yang terperangkap, bukan dari reaksi, karena bahannya dituang terlalu cepat."],"bahas":"Satu-satunya perbedaan adalah cara memasukkan soda kue. Tisu memperlambat pertemuan soda kue dengan cuka, sehingga sumbat sempat dipasang."},{"ind":"inferensi","soal":"Cuka 200 mL (5%) direaksikan dengan soda kue 40 g. Setelah reaksi berhenti, masih ada serbuk putih di dasar botol. Dugaan yang paling masuk akal adalah …","opsi":["Cuka menjadi pereaksi pembatas, dan serbuk itu adalah sisa soda kue yang tidak bereaksi karena asamnya sudah habis.","Serbuk itu adalah zat baru hasil reaksi berupa garam dapur, karena reaksi cuka dan soda kue menghasilkan garam dapur.","Soda kue menjadi pereaksi pembatas, dan serbuk itu adalah cuka yang mengering setelah gasnya keluar dari botol.","Serbuk itu menunjukkan reaksi gagal total, karena reaksi yang berhasil selalu menghabiskan semua bahan awalnya."],"bahas":"Cuka 200 mL mengandung ± 10 g asam asetat yang hanya bereaksi dengan ± 14 g soda kue. Sisa soda kue ± 26 g tidak ikut bereaksi."},{"ind":"evaluasi","soal":"Bayu berkata, \"Pakai cuka biang 25% saja, gasnya lebih banyak dan roketnya lebih jauh.\" Penilaian yang paling tepat adalah …","opsi":["Tidak boleh: cuka biang korosif dan berbahaya bagi kulit dan mata, sehingga dilarang walaupun gasnya lebih banyak.","Tepat: makin pekat cuka, makin banyak gas yang terbentuk, sehingga cuka biang adalah pilihan terbaik untuk lomba.","Tepat: cuka biang dan cuka dapur sama amannya, karena keduanya sama-sama dipakai untuk memasak di rumah.","Kurang tepat: cuka biang justru menghasilkan gas lebih sedikit, karena asam yang pekat tidak dapat bereaksi."],"bahas":"Evaluasi tidak hanya menilai hasil, tetapi juga keselamatan dan aturan. Cuka biang dilarang dalam kendala lomba karena korosif."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap bahwa reaksi cuka dan soda kue termasuk perubahan kimia adalah …","opsi":["Terbentuk zat baru, yaitu gas CO₂, air, dan natrium asetat, yang ditandai gelembung dan suhu turun.","Soda kue larut dalam cuka seperti gula larut dalam air, dan setiap peristiwa melarut termasuk perubahan kimia.","Campurannya bergelembung seperti air mendidih, dan setiap peristiwa yang menghasilkan gelembung adalah perubahan kimia.","Bentuk serbuk soda kue berubah menjadi cair, dan setiap perubahan wujud zat termasuk dalam perubahan kimia."],"bahas":"Ciri utama perubahan kimia adalah terbentuknya zat baru. Melarut dan berubah wujud adalah perubahan fisika; gelembung saja belum cukup sebagai bukti."},{"ind":"regulasi","soal":"Roketmu mendarat di 12 m, padahal prediksimu 20 m. Langkah yang paling tepat adalah …","opsi":["Membandingkan data dengan prediksi, lalu mengubah satu variabel dan menguji ulang untuk mencari sebab.","Menambah cuka dan soda kue sebanyak-banyaknya sekaligus agar roket pasti terbang lebih jauh pada uji berikutnya.","Mengubah prediksi menjadi 12 m agar sesuai dengan hasil uji, lalu menganggap rancanganmu sudah berhasil.","Menyimpulkan bahwa angin adalah satu-satunya penyebab, tanpa memeriksa data uji yang sudah tercatat."],"bahas":"Membandingkan prediksi dengan data lalu memperbaiki rancangan secara terarah adalah inti regulasi diri."}],"B":[{"ind":"interpretasi","soal":"Data uji dengan cuka 300 mL: soda kue 10 g → gas 2,9 L; 15 g → 4,3 L; 20 g → 5,7 L; 30 g → 6,0 L. Makna data yang tepat adalah …","opsi":["Gas bertambah sampai soda kue sekitar 21 g, lalu hampir tetap karena cukanya sudah habis sebagai pembatas.","Gas selalu bertambah sebanding dengan soda kue, sehingga soda kue 40 g pasti menghasilkan gas sekitar 11 L.","Soda kue di atas 20 g menghambat reaksi, karena serbuk yang terlalu banyak menutupi permukaan cuka di botol.","Gas berhenti bertambah karena suhu campuran turun, dan reaksi kimia selalu berhenti ketika suhunya turun."],"bahas":"Cuka 300 mL (± 15 g asam asetat) hanya dapat bereaksi dengan ± 21 g soda kue dan menghasilkan gas ± 6 L. Soda kue di atas itu terbuang."},{"ind":"analisis","soal":"Roket P memakai cuka 5% dan roket Q cuka yang diencerkan menjadi 2,5%, dengan volume cuka dan massa soda kue sama. Gas roket Q lebih sedikit. Penyebab paling tepat adalah …","opsi":["Cuka 2,5% hanya mengandung setengah asam asetat, sehingga asamnya cepat habis dan gas yang terbentuk lebih sedikit.","Air pengencer menyerap seluruh gas CO₂ yang terbentuk, sehingga hampir semua gas hilang ke dalam air.","Cuka yang encer bereaksi lebih lambat, tetapi pada akhirnya selalu menghasilkan gas yang sama banyaknya.","Soda kue tidak dapat bereaksi dengan cuka yang diencerkan, sehingga hanya sebagian kecil reaksi yang terjadi."],"bahas":"Banyaknya gas ditentukan oleh jumlah pereaksi pembatas. Volume cuka sama tetapi kadar asamnya setengah, sehingga asam asetatnya hanya setengah."},{"ind":"inferensi","soal":"Setelah cuka dan soda kue bereaksi, Ayu menyentuh botol dan merasa botolnya lebih dingin. Dugaan yang paling masuk akal adalah …","opsi":["Reaksi itu menyerap kalor dari sekitarnya sehingga suhu turun; ini salah satu ciri perubahan kimia.","Gas CO₂ yang terbentuk adalah gas yang sangat dingin seperti es kering, sehingga botol ikut menjadi dingin.","Botol menjadi dingin karena cuka yang dipakai disimpan di lemari es, bukan karena reaksi yang terjadi.","Suhu turun karena soda kue mencair menjadi cairan, dan setiap zat yang mencair selalu menjadi dingin."],"bahas":"Reaksi cuka dan soda kue menyerap kalor (endoterm). Perubahan suhu adalah salah satu tanda terjadinya reaksi kimia."},{"ind":"evaluasi","soal":"Kelompok Doni mengklaim roketnya terbaik karena mendarat tepat 20 m, tetapi 45% bahannya tidak bereaksi. Penilaian yang paling tepat adalah …","opsi":["Belum terbaik: jaraknya memang tepat, tetapi pereaksi terbuang 45% melebihi batas 20% yang sudah ditetapkan.","Tepat: jarak mendarat adalah satu-satunya kriteria lomba, sehingga bahan yang terbuang tidak perlu dinilai.","Tepat: bahan yang tidak bereaksi tetap berguna sebagai beban roket, sehingga justru membuat roket lebih stabil.","Kurang tepat: roket yang mendarat tepat 20 m pasti memakai bahan yang semuanya bereaksi, jadi data 45% salah."],"bahas":"Rancangan terbaik harus memenuhi semua kriteria, termasuk hemat bahan (pereaksi terbuang paling banyak 20%)."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa roket cuka dapat meluncur adalah …","opsi":["Gas CO₂ menaikkan tekanan; saat sumbat lepas, cairan menyembur ke bawah dan botol terdorong ke atas.","Reaksi cuka dan soda kue menghasilkan api kecil di dalam botol, dan api itulah yang mendorong roket ke atas.","Campuran cuka dan soda kue lebih ringan daripada udara, sehingga botol terangkat ke atas seperti balon gas.","Busa yang terbentuk mengembang dan mengangkat botol, tanpa ada pengaruh tekanan gas di dalam botol."],"bahas":"Gas menaikkan tekanan. Saat sumbat lepas, cairan didorong keluar ke bawah (aksi) dan botol terdorong ke atas (reaksi), sesuai Hukum III Newton."},{"ind":"regulasi","soal":"Kamu sudah lima kali menguji dan selalu mengubah tiga variabel sekaligus. Hasilnya naik-turun tanpa pola. Langkah yang paling tepat adalah …","opsi":["Kembali ke rancangan terbaik, lalu mengubah satu variabel saja pada setiap uji agar pengaruhnya dapat terlihat jelas.","Terus mengubah tiga variabel sekaligus, karena cara itu paling cepat untuk menemukan rancangan yang berhasil.","Memilih hasil uji yang paling bagus dan melaporkannya, tanpa perlu memahami variabel mana yang berpengaruh.","Menyimpulkan bahwa roket cuka memang tidak bisa diatur, sehingga hasilnya selalu ditentukan oleh keberuntungan."],"bahas":"Mengubah banyak variabel sekaligus membuat pola tidak terlihat. Menyadari cara kerja yang keliru lalu memperbaikinya adalah regulasi diri."}]},"roketair":{"tujuan":["Menjelaskan tekanan gas serta hubungan tekanan dengan volume (Hukum Boyle).","Menerapkan Hukum III Newton (aksi–reaksi) untuk menjelaskan gerak roket air.","Merancang roket air yang aman dan tepat sasaran berdasarkan data uji serta batas tekanan."],"A":[{"ind":"interpretasi","soal":"Data uji (botol 1,5 L, tekanan 3 bar): air 200 mL → jarak 35 m; 400 mL → 52 m; 600 mL → 48 m; 900 mL → 30 m. Makna data yang tepat adalah …","opsi":["Ada jumlah air terbaik sekitar 400 mL; air terlalu sedikit atau terlalu banyak memperpendek jarak.","Makin banyak air, makin jauh roket terbang, sehingga botol sebaiknya diisi penuh dengan air sebelum dipompa.","Jumlah air tidak berpengaruh, karena jarak roket hanya ditentukan oleh besarnya tekanan pompa yang diberikan.","Makin sedikit air, makin jauh roket terbang, karena roket yang ringan selalu melesat lebih jauh di udara."],"bahas":"Jarak naik lalu turun, dengan puncak sekitar 400 mL. Air terlalu sedikit berarti sedikit massa dorong; terlalu banyak membuat roket berat dan ruang udaranya sempit."},{"ind":"analisis","soal":"Roket P dan Q identik dan dipompa 3 bar, tetapi roket Q tidak diberi air sama sekali. Roket Q hanya terbang beberapa meter. Penyebab paling tepat adalah …","opsi":["Tanpa air, hampir tidak ada massa yang didorong keluar, sehingga gaya reaksi yang mendorong botol jadi sangat kecil.","Tanpa air, tekanan di dalam botol langsung hilang seluruhnya, karena udara hanya bisa bertahan di dalam botol bila ada air.","Roket Q terlalu ringan, dan benda ringan selalu tertahan udara sehingga tidak dapat terbang tinggi sama sekali.","Udara keluar terlalu lambat dari botol kosong, sehingga dorongannya tidak cukup untuk mengangkat roket ke atas."],"bahas":"Air adalah massa dorong. Udara yang keluar sendiri bermassa sangat kecil, sehingga gaya reaksinya kecil walaupun tekanannya sama."},{"ind":"inferensi","soal":"Saat air menyembur keluar, ruang udara di dalam botol membesar. Dugaan yang paling masuk akal tentang tekanan udaranya adalah …","opsi":["Tekanan udara turun selama air keluar, karena volume udaranya bertambah sedangkan jumlah partikelnya tetap.","Tekanan udara naik selama air keluar, karena udara mendorong air sehingga udara menjadi makin padat dan kuat.","Tekanan udara tetap sama dari awal sampai akhir, karena tidak ada udara yang ditambahkan atau dikeluarkan.","Tekanan udara langsung menjadi nol saat air mulai keluar, karena seluruh udara ikut menyembur bersama air."],"bahas":"Pada suhu tetap, P₁V₁ = P₂V₂. Volume udara membesar saat air keluar, sehingga tekanannya turun dan dorongan roket makin lemah."},{"ind":"evaluasi","soal":"Dimas berkata, \"Pompa sampai 6 bar saja supaya roketnya pasti paling jauh.\" Penilaian yang paling tepat adalah …","opsi":["Tidak boleh: tekanan di atas 4 bar berisiko memecahkan botol bekas, sehingga melanggar batas aman walau jaraknya bertambah.","Tepat: tekanan yang lebih besar selalu membuat roket lebih jauh, sehingga 6 bar adalah pilihan terbaik untuk lomba.","Tepat: botol plastik bekas sangat kuat, sehingga tekanan berapa pun tidak akan membuat botol itu pecah.","Kurang tepat: roket akan melewati pagar di 65 m, tetapi tekanan setinggi itu sebenarnya tetap aman bagi botol."],"bahas":"Batas aman lomba 4 bar ditetapkan karena botol bekas bisa pecah. Keselamatan adalah kendala yang tidak boleh dilanggar demi jarak."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa roket air terdorong ke atas adalah …","opsi":["Udara bertekanan mendorong air keluar ke bawah (aksi), dan air balik mendorong botol ke atas (reaksi).","Air yang keluar mendorong tanah di bawah roket, lalu tanah memantulkan dorongan itu kembali ke arah roket.","Udara di dalam botol lebih ringan daripada udara luar, sehingga botol terangkat ke atas seperti balon udara.","Tekanan udara di luar botol lebih besar daripada di dalam, sehingga udara luar mendorong botol dari bawah."],"bahas":"Hukum III Newton: gaya aksi dan reaksi sama besar dan berlawanan arah. Roket tetap terdorong walaupun semburan airnya tidak mengenai tanah."},{"ind":"regulasi","soal":"Roketmu berputar-putar di udara dan mendarat jauh dari prediksi. Langkah yang paling tepat adalah …","opsi":["Memeriksa kestabilan roket, misalnya sirip atau beban kerucut, lalu mengubah satu hal itu dan menguji ulang.","Menambah tekanan pompa setinggi mungkin, karena roket yang lebih cepat pasti terbang lurus dengan sendirinya.","Menganggap putaran roket sebagai keberuntungan buruk, lalu mengulang uji yang sama tanpa mengubah apa pun.","Mengganti botol, jumlah air, dan sudut peluncuran sekaligus, agar roket berikutnya pasti terbang lurus."],"bahas":"Roket yang berputar menunjukkan masalah kestabilan. Memperbaiki satu bagian lalu menguji ulang membuat penyebabnya dapat dipastikan."}],"B":[{"ind":"interpretasi","soal":"Data uji (air 400 mL, sudut 45°): tekanan 2 bar → 30 m; 3 bar → 45 m; 4 bar → 58 m. Zona target 40–60 m. Kesimpulan yang tepat adalah …","opsi":["Tekanan yang lebih besar menambah jarak; tekanan 3 dan 4 bar sama-sama mendaratkan roket di dalam zona target.","Hanya tekanan 4 bar yang berhasil, karena roket harus mendarat sedekat mungkin dengan batas 60 m untuk menang.","Jarak naik tepat 15 m setiap tekanan naik 1 bar, sehingga pada 6 bar roket pasti mendarat tepat di 88 m.","Tekanan tidak berpengaruh pada jarak, karena perbedaan jarak hanya disebabkan oleh tiupan angin di lapangan."],"bahas":"Jarak 45 m dan 58 m sama-sama berada di zona 40–60 m. Kenaikannya 15 m lalu 13 m, jadi tidak tepat 15 m setiap bar."},{"ind":"analisis","soal":"Dua roket identik diluncurkan; roket A memakai 3 sirip dan kerucut berbeban, roket B tanpa sirip. Roket B terbang lebih pendek dan oleng. Penyebab paling tepat adalah …","opsi":["Tanpa sirip, roket mudah berputar sehingga menembus udara dengan miring dan mengalami hambatan udara yang lebih besar.","Sirip menambah gaya dorong roket A, karena sirip ikut mendorong udara ke bawah saat roket meluncur ke atas.","Roket B lebih ringan, dan roket yang lebih ringan selalu terbang lebih pendek karena mudah tertiup angin.","Kerucut berbeban menambah tekanan udara di dalam botol A, sehingga roket A mendapat dorongan lebih besar."],"bahas":"Sirip di belakang dan beban di depan menjaga roket tetap lurus. Roket yang lurus menembus udara dengan hambatan kecil."},{"ind":"inferensi","soal":"Roket yang sama diluncurkan dengan sudut 45° dan 80°, dengan tekanan dan jumlah air sama. Dugaan yang paling masuk akal adalah …","opsi":["Roket bersudut 80° terbang lebih tinggi tetapi mendarat lebih dekat; sudut 45° membuatnya lebih jauh.","Roket bersudut 80° mendarat lebih jauh, karena roket yang lebih tegak selalu menempuh lintasan yang paling panjang.","Kedua roket mendarat di titik yang sama, karena sudut peluncuran tidak memengaruhi jarak bila tekanannya sama.","Roket bersudut 45° terbang lebih tinggi, karena sudut yang lebih landai membuat roket lebih cepat naik ke atas."],"bahas":"Peluncuran yang hampir tegak memakai sebagian besar kecepatan untuk naik. Jarak mendatar terjauh dicapai di sekitar sudut 45°."},{"ind":"evaluasi","soal":"Kelompok Ayu mengklaim, \"Roket kami terbaik karena mendarat di 63 m, paling jauh di kelas.\" Penilaian yang paling tepat adalah …","opsi":["Belum terbaik: zona targetnya 40–60 m, jadi mendarat di 63 m berarti sudah meleset dan hampir mencapai pagar.","Tepat: roket yang paling jauh selalu merupakan roket terbaik, sehingga kelompok Ayu pantas menjadi juara.","Tepat: selisih 3 m dari zona target masih wajar, sehingga roket itu dapat dianggap mendarat di zona target.","Kurang tepat: roket air tidak mungkin terbang lebih dari 60 m, jadi pengukuran jarak kelompok Ayu pasti salah."],"bahas":"Kriterianya tepat sasaran, bukan paling jauh. Melewati zona target juga berbahaya karena mendekati pagar lapangan."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa memompa udara membuat tekanan di dalam botol naik adalah …","opsi":["Memompa menambah jumlah partikel udara di ruang yang sama, sehingga tumbukan partikel ke dinding botol makin sering.","Memompa membuat udara di dalam botol menjadi lebih panas, dan hanya panas itulah yang menaikkan tekanannya.","Memompa memperbesar ukuran setiap partikel udara, sehingga partikel saling berdesakan menekan dinding botol dari dalam.","Memompa mendorong air keluar dari botol, dan air yang keluar itulah yang menaikkan tekanan udara di dalamnya."],"bahas":"Tekanan gas berasal dari tumbukan partikel dengan dinding wadah. Lebih banyak partikel dalam volume yang sama berarti tumbukan lebih sering."},{"ind":"regulasi","soal":"Kamu menulis prediksi jarak 50 m, tetapi hasilnya 38 m. Sikap yang paling tepat adalah …","opsi":["Menganggap selisih itu sebagai petunjuk, lalu memeriksa faktor yang mungkin berbeda dan menguji ulang secara teratur.","Mengubah catatan prediksi menjadi 38 m, karena prediksi yang meleset menunjukkan bahwa kamu kurang pintar.","Mengabaikan prediksi pada uji berikutnya, karena menebak hasil sebelum menguji sama sekali tidak ada gunanya.","Menyalahkan pompa tanpa memeriksanya, karena prediksimu sudah dihitung dengan sangat teliti sebelumnya."],"bahas":"Prediksi yang meleset bukan kegagalan, tetapi bahan belajar. Pemikir kritis memakai selisih itu untuk memperbaiki pemahamannya."}]},"jembatan":{"tujuan":["Mengidentifikasi gaya tekan dan gaya tarik pada batang jembatan yang dibebani.","Menganalisis pengaruh bentuk rangka, tinggi, dan tumpukan stik terhadap kekuatan dan efisiensi jembatan.","Mengevaluasi rancangan jembatan berdasarkan kekuatan, efisiensi, dan kendala bahan."],"A":[{"ind":"interpretasi","soal":"Data uji rangka Warren: tinggi 4 cm → menahan 9 kg; 8 cm → 17 kg; 12 cm → 14 kg (mulai terpuntir ke samping). Makna data yang tepat adalah …","opsi":["Rangka lebih tinggi awalnya lebih kuat, tetapi bila terlalu tinggi dan ramping justru mudah terpuntir.","Makin tinggi rangka, makin kuat jembatan, sehingga rangka setinggi 15 cm pasti menahan beban yang paling besar.","Tinggi rangka tidak berpengaruh, karena kekuatan jembatan hanya ditentukan oleh jumlah stik yang dipakai.","Makin rendah rangka, makin kuat jembatan, karena rangka yang rendah lebih dekat ke tumpuan di kedua ujungnya."],"bahas":"Kekuatan naik dari 9 ke 17 kg, lalu turun ke 14 kg karena rangka terpuntir. Ada tinggi rangka yang paling baik."},{"ind":"analisis","soal":"Saat jembatan balok datar dibebani di tengah, bagian atasnya memendek dan bagian bawahnya meregang. Pernyataan yang tepat adalah …","opsi":["Bagian atas menerima gaya tekan dan bagian bawah menerima gaya tarik, sehingga cara gagal keduanya pun berbeda.","Bagian atas menerima gaya tarik dan bagian bawah menerima gaya tekan, karena beban menarik bagian atas ke bawah.","Seluruh bagian balok menerima gaya tekan yang sama besar, karena beban menekan balok dari atas secara merata.","Bagian atas dan bawah tidak menerima gaya apa pun, karena seluruh beban langsung diteruskan ke kedua tumpuan."],"bahas":"Memendek berarti tertekan, meregang berarti tertarik. Batang tekan cenderung menekuk, batang tarik cenderung putus di sambungan."},{"ind":"inferensi","soal":"Jembatan rangka dari stik satu lapis patah: batang atas yang panjang melengkung dulu sebelum patah. Dugaan yang paling masuk akal adalah …","opsi":["Batang atas menerima gaya tekan dan menekuk karena tipis; menumpuk stik agar lebih kaku kemungkinan menolong.","Batang atas menerima gaya tarik dan putus di sambungan, sehingga lemnya perlu diganti dengan lem yang lebih kuat.","Kayu stik es krim terlalu lunak, sehingga jembatan dari stik tidak akan pernah mampu menahan beban yang besar.","Bebannya diletakkan terlalu ke pinggir, sehingga batang atas melengkung karena beban tidak berada di tengah."],"bahas":"Melengkung sebelum patah adalah tanda tekuk pada batang tekan yang panjang dan tipis. Batang yang ditumpuk menjadi jauh lebih kaku."},{"ind":"evaluasi","soal":"Ilham berkata, \"Jembatan kami paling bagus karena menahan 30 kg.\" Jembatan itu memakai 160 stik. Penilaian yang paling tepat adalah …","opsi":["Belum tentu terbaik: kuat menahan 30 kg, tetapi memakai 160 stik melebihi batas 120 stik dan perlu dicek efisiensinya.","Tepat: beban terbesar adalah satu-satunya ukuran jembatan terbaik, sehingga jumlah stik tidak perlu diperhatikan.","Tepat: jembatan yang memakai lebih banyak stik pasti lebih efisien, karena bahannya lebih banyak menahan beban.","Kurang tepat: jembatan stik tidak mungkin menahan 30 kg, sehingga pengukuran kelompok Ilham pasti keliru."],"bahas":"Rancangan harus memenuhi kendala bahan (paling banyak 120 stik) dan kriteria efisiensi, bukan hanya kekuatan."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa rangka jembatan disusun dari bentuk segitiga adalah …","opsi":["Segitiga tidak berubah bentuk bila sambungannya kuat, sehingga beban tersalur sebagai tekan dan tarik.","Segitiga memakai stik paling sedikit dibanding bentuk lain, sehingga jembatan menjadi paling murah dan ringan.","Bentuk segitiga terlihat paling indah dan kokoh, sehingga para insinyur selalu memilihnya untuk setiap jembatan.","Segitiga membuat beban berpindah ke udara di sekitar jembatan, sehingga batang-batangnya tidak menerima gaya."],"bahas":"Segi empat bisa miring menjadi jajar genjang, tetapi segitiga tidak. Karena itu rangka segitiga kaku dan menyalurkan beban lewat batang-batangnya."},{"ind":"regulasi","soal":"Jembatanmu selalu patah di sambungan lem batang bawah. Langkah yang paling tepat adalah …","opsi":["Memperbaiki kekuatan sambungan, misalnya jenis lem atau luas tempelannya, lalu menguji ulang jembatannya.","Mengganti bentuk rangka, tinggi, dan jumlah lapisan sekaligus, agar jembatan berikutnya pasti tidak patah lagi.","Mengurangi beban uji sampai jembatan tidak patah, lalu melaporkan beban itu sebagai kekuatan jembatanmu.","Menyimpulkan bahwa stik es krim memang lemah, sehingga tidak ada gunanya memperbaiki jembatan itu lagi."],"bahas":"Pola kegagalan yang berulang menunjukkan titik lemah. Memperbaiki bagian itu saja lalu menguji ulang adalah perbaikan yang terarah."}],"B":[{"ind":"interpretasi","soal":"Data uji: balok datar → beban maksimum 4 kg, massa 300 g; rangka Pratt → 18 kg, massa 200 g. Kriteria: menahan ≥ 15 kg dan efisiensi ≥ 80. Kesimpulan yang tepat adalah …","opsi":["Rangka Pratt memenuhi kedua kriteria (efisiensi 90), sedangkan balok datar gagal karena jauh terlalu lemah.","Balok datar lebih baik, karena massanya lebih besar sehingga lebih kokoh untuk menahan beban yang berat.","Keduanya gagal, karena efisiensi dihitung dari jumlah stik, bukan dari beban maksimum dan massa jembatan yang diuji.","Rangka Pratt memenuhi kriteria kekuatan, tetapi efisiensinya hanya 9 sehingga belum memenuhi syarat 80."],"bahas":"Efisiensi = beban maksimum ÷ massa jembatan = 18.000 g ÷ 200 g = 90. Balok datar: 4.000 g ÷ 300 g ≈ 13."},{"ind":"analisis","soal":"Dua jembatan Warren identik, tetapi batang jembatan P satu lapis dan jembatan Q tiga lapis stik. Jembatan Q menahan beban jauh lebih besar. Penyebab paling tepat adalah …","opsi":["Batang tiga lapis jauh lebih kaku, sehingga batang tekan tidak mudah menekuk sebelum kayu stiknya benar-benar hancur.","Batang tiga lapis membuat jembatan lebih tinggi, dan jembatan yang lebih tinggi selalu menahan beban lebih besar.","Lapisan stik menambah berat jembatan, dan jembatan yang lebih berat selalu lebih kuat menahan beban di tengah.","Lem pada tiga lapis lebih banyak, dan kekuatan jembatan hanya ditentukan oleh banyaknya lem yang dipakai."],"bahas":"Hanya jumlah lapisan yang berbeda. Batang yang lebih tebal jauh lebih tahan terhadap tekuk, yaitu cara gagal utama batang tekan."},{"ind":"inferensi","soal":"Jembatan busur menahan beban besar saat tumpuannya dijepit, tetapi langsung ambruk saat tumpuannya bisa bergeser. Dugaan yang paling masuk akal adalah …","opsi":["Busur mendorong tumpuan ke samping; bila tumpuan bergeser, busur melebar lalu runtuh begitu saja.","Busur menarik tumpuan ke tengah; bila tumpuan bergeser, busur menjadi terlalu sempit sehingga patah di puncaknya.","Tumpuan yang dijepit menambah jumlah stik busur, sehingga busur menjadi lebih kuat menahan beban di tengah.","Busur hanya kuat bila diletakkan di permukaan yang kasar, karena gesekan membuat beban berpindah ke meja."],"bahas":"Busur menyalurkan beban sebagai gaya tekan yang mendorong tumpuan ke luar. Tanpa penahan, kaki busur melebar dan busur runtuh."},{"ind":"evaluasi","soal":"Kelompok Rina memilih lem tembak karena \"paling cepat kering, jadi pasti paling kuat\". Penilaian yang paling tepat adalah …","opsi":["Belum tentu: cepat kering tidak sama dengan kuat; kekuatannya perlu dibandingkan lewat uji beban nyata.","Tepat: lem yang paling cepat kering selalu menghasilkan sambungan paling kuat untuk semua jenis bahan.","Tepat: jenis lem tidak berpengaruh pada kekuatan, sehingga sebaiknya dipilih lem yang paling cepat kering.","Kurang tepat: lem tembak tidak dapat merekatkan kayu sama sekali, sehingga jembatan pasti langsung lepas."],"bahas":"Klaim yang mengaitkan dua sifat berbeda (cepat kering dan kuat) harus dibuktikan dengan data, misalnya uji beban dengan lem berbeda."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa menaikkan tinggi rangka (sampai batas tertentu) membuat jembatan lebih kuat adalah …","opsi":["Gaya pada batang atas dan bawah sebanding dengan momen dibagi tinggi rangka, jadi rangka tinggi memperkecilnya.","Rangka yang tinggi membuat beban berada lebih jauh dari tanah, sehingga gaya gravitasi pada beban menjadi kecil.","Rangka yang tinggi memakai lebih banyak stik, dan jumlah stik adalah satu-satunya penentu kekuatan jembatan.","Rangka yang tinggi membuat jembatan lebih berat, sehingga beban di tengah tertahan oleh berat jembatan itu."],"bahas":"Gaya batang ≈ momen ÷ tinggi rangka. Momen tetap untuk beban yang sama, jadi rangka yang lebih tinggi memperkecil gaya pada batang."},{"ind":"regulasi","soal":"Setelah tiga kali uji, kamu sadar beban selalu diletakkan pada posisi yang sedikit berbeda. Sikap yang paling tepat adalah …","opsi":["Menandai posisi beban tepat di tengah dan mengulang uji, karena posisi beban yang berubah membuat uji tidak adil.","Mengabaikan posisi beban, karena yang dinilai hanya berapa kilogram beban yang dapat ditahan jembatan.","Memilih hasil uji yang paling besar, karena hasil itu paling menguntungkan untuk dilaporkan kepada juri.","Menghentikan uji, karena perbedaan posisi beban berarti semua data sebelumnya harus dibuang tanpa sisa."],"bahas":"Posisi beban adalah variabel kontrol. Menyadari kesalahan cara uji lalu memperbaikinya adalah bentuk regulasi diri."}]},"angin":{"tujuan":["Menjelaskan perubahan energi pada pembangkit listrik tenaga angin dan prinsip induksi elektromagnetik.","Menganalisis pengaruh kecepatan angin, panjang, jumlah, dan sudut bilah, serta gir terhadap daya listrik.","Merancang kincir yang memenuhi kebutuhan daya, mudah berputar, dan kuat berdasarkan data."],"A":[{"ind":"interpretasi","soal":"Data uji kincir yang sama: angin 2 m/s → daya 0,1 W; 4 m/s → 0,9 W; 6 m/s → 3,0 W. Makna data yang tepat adalah …","opsi":["Daya naik lebih cepat daripada kecepatan angin; angin dua kali lebih kencang memberi daya berlipat.","Daya naik sebanding dengan kecepatan angin, sehingga angin dua kali lebih kencang selalu memberi daya dua kali.","Kecepatan angin tidak berpengaruh, karena daya listrik hanya ditentukan oleh jenis generator yang dipasang.","Daya naik tepat 0,8 W setiap angin bertambah 2 m/s, sehingga pada 8 m/s kincir pasti menghasilkan 3,8 W."],"bahas":"Dari 2 ke 4 m/s, daya naik sekitar 9 kali. Daya angin sebanding dengan pangkat tiga kecepatan (2³ = 8), ditambah pengaruh hambatan generator."},{"ind":"analisis","soal":"Kincir dengan gir 1 : 10 menghasilkan daya besar pada angin kencang, tetapi tidak mau mulai berputar pada angin 3 m/s. Penyebab paling tepat adalah …","opsi":["Gir besar mempercepat generator, tetapi membuat kincir lebih berat untuk mulai berputar saat angin pelan.","Gir besar mengurangi daya angin yang masuk, sehingga angin pelan sama sekali tidak dapat menggerakkan bilah.","Gir besar membuat bilah lebih ringan, sehingga bilah mudah terbawa angin dan tidak berputar dengan teratur.","Generator tidak dapat bekerja dengan gir, sehingga kincir baru berputar bila gir dilepas seluruhnya."],"bahas":"Gir menukar putaran dengan gaya putar. Generator berputar lebih cepat, tetapi bilah harus melawan hambatan awal yang lebih besar."},{"ind":"inferensi","soal":"Panjang bilah kincir ditambah dari 20 cm menjadi 40 cm, sedangkan hal lain tetap. Dugaan yang paling masuk akal tentang daya angin yang tertangkap adalah …","opsi":["Daya yang tertangkap kira-kira empat kali lebih besar, karena luas sapuan sebanding kuadrat dari panjang bilah.","Daya angin yang tertangkap tepat dua kali lebih besar, karena panjang bilah juga bertambah tepat dua kali lipat.","Daya angin yang tertangkap tetap sama, karena kecepatan angin yang melewati kincir sama sekali tidak berubah.","Daya angin yang tertangkap berkurang, karena bilah yang lebih panjang lebih berat dan lebih sulit diputar."],"bahas":"Luas sapuan A = π × r². Jari-jari dua kali lipat membuat luas empat kali lipat, sehingga daya angin yang melewati kincir juga empat kali."},{"ind":"evaluasi","soal":"Andi berkata, \"Kincirku bisa menangkap 90% energi angin kalau bilahnya diatur pas.\" Penilaian yang paling tepat adalah …","opsi":["Tidak mungkin: menurut batas Betz, kincir paling banyak menangkap 59% energi angin, dan kincir sederhana jauh di bawahnya.","Mungkin: dengan sudut bilah yang tepat, kincir dapat menangkap hampir seluruh energi angin yang melewatinya.","Mungkin: makin banyak bilah yang dipasang, makin besar persentase energi angin yang dapat ditangkap kincir.","Tidak mungkin: kincir hanya dapat menangkap 10% energi angin, sehingga 90% energi angin selalu terbuang."],"bahas":"Batas Betz (59%) berlaku untuk semua kincir. Kincir sederhana biasanya hanya menangkap 15–30% energi angin."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap tentang perubahan energi pada pembangkit listrik tenaga angin adalah …","opsi":["Energi kinetik angin memutar bilah, lalu magnet berputar di dekat kumparan sehingga timbul arus listrik.","Angin mengandung listrik statis, lalu bilah kincir mengumpulkan listrik itu dan mengalirkannya ke lampu LED.","Energi panas matahari dibawa angin ke bilah, lalu bilah mengubah panas itu langsung menjadi cahaya lampu.","Generator menciptakan energi listrik baru dari putaran, sehingga energi listrik lebih besar daripada energi angin."],"bahas":"Energi kinetik → energi gerak bilah → energi listrik (induksi elektromagnetik) → energi cahaya. Energi berubah bentuk, tidak diciptakan."},{"ind":"regulasi","soal":"Kincirmu hanya menghasilkan 0,4 W pada angin 4 m/s, padahal targetnya 1 W. Langkah yang paling tepat adalah …","opsi":["Mencari faktor yang paling membatasi, misalnya panjang atau sudut bilah, lalu mengubahnya satu per satu.","Menguji pada angin 10 m/s agar daya pasti melebihi 1 W, lalu melaporkan bahwa target daya 1 W sudah tercapai.","Mengganti bilah, generator, dan gir sekaligus, agar daya pada uji berikutnya pasti melampaui target.","Menyimpulkan bahwa angin di pantai memang terlalu lemah, sehingga rancangan tidak perlu diperbaiki."],"bahas":"Target diukur pada angin 4 m/s; mengubah kondisi uji tidak jujur. Mengubah satu faktor membantu menemukan penyebab daya yang rendah."}],"B":[{"ind":"interpretasi","soal":"Data uji pada angin 4 m/s: sudut bilah 5° → 0,3 W; 15° → 1,1 W; 30° → 0,8 W; 45° → 0,4 W. Makna data yang tepat adalah …","opsi":["Ada sudut bilah terbaik sekitar 15°; sudut terlalu kecil atau terlalu besar sama-sama menurunkan dayanya.","Makin besar sudut bilah, makin besar daya listrik, sehingga sudut 45° seharusnya memberi hasil yang terbaik.","Sudut bilah tidak berpengaruh pada daya, karena daya hanya bergantung pada kecepatan angin yang bertiup.","Makin kecil sudut bilah, makin besar daya listrik, karena bilah yang datar lebih mudah menangkap angin."],"bahas":"Daya naik dari 5° ke 15°, lalu turun pada 30° dan 45°. Pola naik-turun menunjukkan ada sudut optimum."},{"ind":"analisis","soal":"Kincir berbilah kardus dayanya bagus pada angin 4 m/s, tetapi bilahnya patah saat diuji pada angin 10 m/s. Penjelasan yang paling tepat adalah …","opsi":["Gaya angin bertambah besar pada angin kencang, dan kardus terlalu lemah menahannya, sehingga bahan bilah perlu diganti.","Bilah kardus menyerap air dari udara laut, sehingga bilah patah karena basah, bukan karena kuatnya angin.","Angin 10 m/s terlalu dingin bagi kardus, sehingga kardus menjadi rapuh lalu patah saat bilah berputar.","Kincir berputar terlalu lambat pada angin kencang, sehingga bilah kardus tertekuk karena berat sendiri."],"bahas":"Gaya angin pada bilah naik tajam saat angin kencang. Bahan bilah harus cukup kuat untuk kondisi terburuk, bukan hanya kondisi biasa."},{"ind":"inferensi","soal":"Angin di pantai pada sore hari 4 m/s dan pada malam hari 2 m/s. Dugaan yang paling masuk akal tentang daya angin pada malam hari adalah …","opsi":["Daya angin malam kira-kira seperdelapan daya sore, karena daya sebanding pangkat tiga kecepatan.","Daya angin malam tepat setengah daya sore, karena kecepatan anginnya juga turun menjadi setengahnya.","Daya angin malam sama dengan sore, karena kincir tetap berputar walaupun kecepatan anginnya berkurang.","Daya angin malam menjadi nol, karena kincir angin sama sekali tidak dapat berputar pada angin 2 m/s."],"bahas":"Kecepatan turun setengah, sehingga daya turun menjadi (½)³ = ⅛. Pangkat tiga membuat perubahan kecepatan sangat berpengaruh."},{"ind":"evaluasi","soal":"Kelompok Tari mengklaim kincirnya terbaik karena menghasilkan 3 W, tetapi baru mulai berputar pada angin 5 m/s. Penilaian yang paling tepat adalah …","opsi":["Belum terbaik: dayanya besar, tetapi kincir harus sudah berputar pada angin 3 m/s, jadi belum memenuhinya.","Tepat: daya listrik terbesar adalah satu-satunya ukuran kincir terbaik, sehingga kriteria lain tidak penting.","Tepat: kincir yang sulit berputar pasti lebih kuat, sehingga kincir itu justru lebih tahan saat angin kencang.","Kurang tepat: kincir mini tidak mungkin menghasilkan 3 W, sehingga pengukuran kelompok Tari pasti keliru."],"bahas":"Kincir yang baru berputar pada 5 m/s tidak berguna saat angin pelan. Semua kriteria harus dipenuhi."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa energi listrik yang dihasilkan selalu lebih kecil daripada energi angin adalah …","opsi":["Sebagian energi tidak tertangkap bilah, dan sebagian lagi berubah menjadi panas dan bunyi akibat gesekan poros.","Sebagian energi angin musnah saat menabrak bilah, karena energi dapat hilang begitu saja tanpa berubah bentuk.","Generator selalu menyimpan setengah energinya sebagai cadangan, sehingga hanya setengahnya yang sampai ke lampu.","Lampu LED menolak sebagian energi listrik, sehingga energi yang tidak terpakai kembali menjadi energi angin."],"bahas":"Energi tidak musnah. Bagian yang tidak menjadi listrik tetap ada sebagai energi angin yang lewat, panas, dan bunyi."},{"ind":"regulasi","soal":"Kincirmu memenuhi target daya di simulasi, tetapi model nyatanya hanya menghasilkan setengahnya. Sikap yang paling tepat adalah …","opsi":["Mencari faktor nyata yang tidak dihitung simulasi, misalnya gesekan poros, lalu memperbaikinya dan mengukur ulang.","Menyimpulkan bahwa simulasi pasti salah, sehingga hasil simulasi tidak perlu dipakai lagi dalam merancang.","Melaporkan hasil simulasi saja, karena hasil simulasi lebih bagus daripada hasil pengukuran model nyata.","Menyimpulkan bahwa model nyata pasti salah buat, lalu berhenti tanpa mencari tahu penyebab perbedaannya."],"bahas":"Simulasi adalah model yang disederhanakan. Selisih dengan hasil nyata menjadi petunjuk faktor yang belum diperhitungkan."}]},"listrik":{"tujuan":["Menerapkan Hukum Ohm untuk menghubungkan tegangan, arus, dan hambatan.","Membedakan sifat rangkaian seri dan paralel serta kegunaannya.","Merancang lampu darurat yang terang, awet, dan aman berdasarkan data uji serta kendala."],"A":[{"ind":"interpretasi","soal":"Data uji LED dengan 3 baterai (4,5 V): resistor 47 Ω → arus 34 mA (LED putus); 100 Ω → 16 mA (menyala); 220 Ω → 7 mA (redup). Makna data yang tepat adalah …","opsi":["Resistor lebih besar memperkecil arus; 100 Ω membuat LED aman, sedangkan 47 Ω terlalu kecil.","Resistor yang lebih besar memperbesar arus, sehingga resistor 220 Ω seharusnya membuat LED menyala paling terang.","Besar resistor tidak berpengaruh pada arus, karena arus hanya ditentukan oleh jumlah baterai yang dipakai.","Resistor 47 Ω paling baik karena arusnya paling besar, dan LED selalu lebih awet bila arusnya besar."],"bahas":"Sesuai Hukum Ohm, hambatan lebih besar memperkecil arus. LED putus di atas ± 30 mA, sehingga 47 Ω terlalu kecil dan 220 Ω terlalu besar."},{"ind":"analisis","soal":"Pada rangkaian seri tiga lampu, satu lampu dicabut dan semua lampu padam. Pada rangkaian paralel, lampu lain tetap menyala. Penyebab paling tepat adalah …","opsi":["Rangkaian seri hanya punya satu jalur arus yang terputus, sedangkan paralel punya cabang lain yang masih utuh.","Lampu pada rangkaian seri saling meminjam tenaga, sehingga satu lampu dicabut membuat lampu lain kehabisan tenaga.","Rangkaian paralel memakai baterai lebih banyak, sehingga lampunya tetap menyala walaupun satu lampu dicabut.","Lampu pada rangkaian seri lebih mudah rusak, sehingga semua lampu ikut padam bila salah satu lampu dicabut."],"bahas":"Arus hanya mengalir bila jalurnya tertutup. Pada rangkaian seri, mencabut satu lampu memutus satu-satunya jalur."},{"ind":"inferensi","soal":"Lampu darurat menarik arus total 250 mA dari baterai berkapasitas 2000 mAh. Dugaan lama nyala yang paling masuk akal adalah …","opsi":["Sekitar 8 jam, karena lama nyala kira-kira sama dengan kapasitas baterai dibagi arus yang mengalir keluar.","Sekitar 2.250 jam, karena lama nyala diperoleh dengan menjumlahkan kapasitas baterai dan arus yang mengalir.","Sekitar 0,125 jam, karena lama nyala diperoleh dengan membagi arus dengan kapasitas baterai yang dipakai.","Lama nyala tidak bisa diperkirakan, karena lamanya hanya ditentukan oleh warna cahaya lampu yang dipakai."],"bahas":"Lama nyala ≈ kapasitas ÷ arus = 2000 mAh ÷ 250 mA = 8 jam."},{"ind":"evaluasi","soal":"Rudi berkata, \"Pakai bohlam pijar saja, lebih terang dan murah, pasti tahan semalam.\" Penilaian yang paling tepat adalah …","opsi":["Belum tentu: bohlam pijar boros energi dan arusnya besar, sehingga baterai cepat habis; perlu dicek dengan data uji.","Tepat: bohlam pijar selalu lebih hemat daripada LED, sehingga baterainya pasti tahan lebih dari satu malam.","Tepat: lampu yang lebih terang selalu lebih awet, karena cahayanya keluar lebih kuat dari baterai.","Kurang tepat: bohlam pijar tidak dapat menyala dengan baterai, sehingga lampu itu sama sekali tidak berguna."],"bahas":"Bohlam pijar mengubah banyak energi menjadi panas. Untuk terang yang sama, arusnya lebih besar sehingga baterai lebih cepat habis."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa LED perlu dipasang bersama resistor pembatas adalah …","opsi":["Tanpa resistor, arus terlalu besar dan LED bisa putus; resistor memperkecil arus sesuai Hukum Ohm.","Resistor menambah tegangan baterai, sehingga LED mendapat dorongan listrik yang cukup untuk menyala terang.","Resistor menyimpan listrik cadangan, sehingga LED tetap menyala beberapa saat setelah baterai dilepas.","Resistor mengubah arus searah menjadi arus bolak-balik, karena LED hanya dapat menyala dengan arus bolak-balik."],"bahas":"I = V ÷ R. Menambah hambatan memperkecil arus sampai berada di bawah batas aman LED."},{"ind":"regulasi","soal":"Rangkaianmu menyala terang, tetapi kamu lupa memeriksa kriteria \"lampu lain tetap menyala bila satu dicabut\". Langkah yang paling tepat adalah …","opsi":["Menguji dengan mencabut satu lampu, lalu memperbaiki susunan rangkaian bila ternyata lampu lain padam.","Menganggap kriteria itu sudah terpenuhi, karena rangkaian yang terang biasanya juga tahan bila lampu dicabut.","Melewati kriteria itu, karena yang terpenting dari lampu darurat hanyalah cahayanya yang terang.","Mengganti semua lampu dengan lampu baru, agar tidak ada lampu yang perlu dicabut saat dipakai."],"bahas":"Memeriksa semua kriteria secara jujur, termasuk yang belum diuji, adalah bagian dari regulasi diri."}],"B":[{"ind":"interpretasi","soal":"Data uji 3 LED paralel dengan 3 baterai: tiap LED 16 mA, cahaya total 18 lumen, lama nyala 41 jam. Kriteria: ≥ 15 lumen dan ≥ 8 jam. Kesimpulan yang tepat adalah …","opsi":["Rancangan memenuhi kriteria terang dan lama nyala; arus total 48 mA cukup kecil sehingga baterainya awet.","Rancangan gagal, karena tiap LED hanya mendapat 16 mA sehingga cahayanya pasti terlalu redup untuk membaca.","Rancangan gagal, karena lama nyala 41 jam terlalu lama dan membuat baterai menjadi panas dan berbahaya.","Rancangan memenuhi kriteria terang, tetapi lama nyalanya dihitung dari arus satu LED saja, yaitu 125 jam."],"bahas":"Pada rangkaian paralel, arus total adalah jumlah arus cabang: 3 × 16 = 48 mA. Lama nyala ≈ 2000 ÷ 48 ≈ 41 jam."},{"ind":"analisis","soal":"Dua baterai seri (3 V) menyalakan satu LED dengan redup, sedangkan tiga baterai seri (4,5 V) membuatnya lebih terang. Penjelasan yang paling tepat adalah …","opsi":["Baterai seri menjumlahkan tegangan, sehingga dengan hambatan yang sama arus yang mengalir ke LED menjadi lebih besar.","Baterai seri menjumlahkan kapasitas, sehingga LED mendapat cadangan listrik lebih banyak dan menyala lebih terang.","Baterai ketiga menambah warna cahaya LED, sehingga cahaya LED terlihat lebih terang di mata kita.","Tegangan baterai tidak berpengaruh, karena terang LED hanya ditentukan oleh jenis kabel yang dipakai."],"bahas":"Baterai seri menjumlahkan tegangan. Tegangan lebih besar dengan hambatan yang sama menghasilkan arus lebih besar (I = V ÷ R)."},{"ind":"inferensi","soal":"Empat LED disusun seri dengan 3 baterai (4,5 V), dan LED tidak menyala sama sekali. Dugaan yang paling masuk akal adalah …","opsi":["Tegangan 4,5 V terbagi ke empat LED, sehingga tiap LED mendapat jauh di bawah tegangan nyalanya.","Arus pada rangkaian seri terlalu besar, sehingga keempat LED langsung putus begitu saklar dinyalakan.","Baterai tidak dapat dipakai untuk rangkaian seri, sehingga LED hanya menyala bila dirangkai paralel.","Salah satu LED dipasang terbalik, karena LED yang dirangkai seri tidak pernah gagal menyala karena tegangan."],"bahas":"Pada rangkaian seri, tegangan sumber terbagi. 4,5 V dibagi empat LED hanya ± 1,1 V per LED, jauh di bawah tegangan nyala LED."},{"ind":"evaluasi","soal":"Kelompok Lia mengklaim, \"Lampu kami terbaik, terangnya 40 lumen!\" Ternyata baterainya hanya tahan 3 jam. Penilaian yang paling tepat adalah …","opsi":["Belum terbaik: terangnya jauh melebihi syarat, tetapi lama nyala 3 jam tidak memenuhi syarat minimal 8 jam.","Tepat: lampu yang paling terang selalu merupakan lampu darurat terbaik, sehingga lama nyala tidak penting.","Tepat: lama nyala 3 jam sudah cukup untuk belajar, sehingga syarat 8 jam boleh diabaikan oleh kelompok Lia.","Kurang tepat: lampu darurat dari baterai AA tidak mungkin seterang 40 lumen, jadi pengukurannya pasti salah."],"bahas":"Lampu darurat harus tahan semalam. Terang yang berlebihan menguras baterai sehingga kriteria lama nyala tidak terpenuhi."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa listrik di rumah dipasang secara paralel adalah …","opsi":["Setiap cabang mendapat tegangan penuh dan bisa menyala sendiri, jadi satu lampu putus tak memadamkan lainnya.","Rangkaian paralel memakai kabel lebih sedikit, sehingga biaya pemasangan listrik di rumah menjadi paling murah.","Rangkaian paralel membuat arus total menjadi nol, sehingga tagihan listrik rumah menjadi jauh lebih hemat.","Rangkaian paralel menurunkan tegangan di setiap lampu, sehingga lampu rumah tidak mudah putus karena panas."],"bahas":"Pada rangkaian paralel, setiap cabang mendapat tegangan sumber penuh dan punya jalurnya sendiri."},{"ind":"regulasi","soal":"Kamu menghitung lama nyala 20 jam, tetapi lampu nyatamu padam setelah 12 jam. Sikap yang paling tepat adalah …","opsi":["Memeriksa ulang perhitungan dan kondisi nyata, misalnya kapasitas baterai bekas, lalu memperbaiki perkiraanmu.","Menyimpulkan bahwa rumus lama nyala tidak berguna, sehingga perhitungan tidak perlu dipakai lagi ke depannya.","Menuliskan hasil 20 jam di laporan, karena hasil perhitungan lebih dapat dipercaya daripada pengukuran.","Menyalahkan lampu tanpa memeriksa apa pun, karena perhitunganmu sudah pasti benar sejak awal."],"bahas":"Perhitungan memakai anggapan, misalnya kapasitas baterai penuh. Membandingkannya dengan hasil nyata membantu memperbaiki perkiraan."}]},"magnet":{"tujuan":["Membedakan bahan magnetik dan nonmagnetik serta menjelaskan sifat kutub magnet.","Menganalisis faktor yang memengaruhi kekuatan elektromagnet (jumlah lilitan, arus, dan inti).","Merancang derek elektromagnet yang kuat, dapat melepas benda, dan hemat energi berdasarkan data."],"A":[{"ind":"interpretasi","soal":"Data uji inti paku besi: 50 lilitan → mengangkat 6 paku; 100 lilitan → 13 paku; 150 lilitan → 18 paku (kawat mulai hangat). Makna data yang tepat adalah …","opsi":["Lilitan lebih banyak memperkuat elektromagnet, tetapi kawat mulai hangat sehingga panas perlu diperhatikan.","Lilitan yang lebih banyak memperlemah elektromagnet, sehingga 50 lilitan seharusnya mengangkat paku terbanyak.","Jumlah lilitan tidak berpengaruh, karena kekuatan elektromagnet hanya ditentukan oleh jenis paku yang diangkat.","Paku yang terangkat bertambah tepat 6 setiap lilitan ditambah 50, sehingga 300 lilitan pasti mengangkat 36 paku."],"bahas":"Jumlah paku naik (6 → 13 → 18), tetapi kenaikannya tidak tetap. Kawat yang menghangat adalah tanda arus dan panas perlu dijaga."},{"ind":"analisis","soal":"Elektromagnet berinti baut baja mengangkat banyak paku, tetapi paku tetap menempel setelah saklar dimatikan. Penyebab paling tepat adalah …","opsi":["Baja sulit kehilangan kemagnetannya dan menjadi magnet tetap, sehingga paku masih tertarik saat arus diputus.","Arus listrik masih tersimpan di kawat setelah saklar dimatikan, sehingga elektromagnet tetap bekerja sebentar.","Paku menjadi lengket karena panas dari kawat, sehingga paku menempel pada baut, bukan karena gaya magnet.","Baja menyerap kemagnetan paku, sehingga paku berubah menjadi magnet yang menarik baut baja ke arahnya."],"bahas":"Baja menyimpan sisa kemagnetan. Karena itu baja cocok untuk magnet tetap, tetapi kurang cocok untuk derek yang harus melepas benda."},{"ind":"inferensi","soal":"Elektromagnet yang sama dipakai menguji paku, klip kertas, dan potongan kaleng aluminium. Dugaan yang paling masuk akal adalah …","opsi":["Paku dan klip tertarik karena terbuat dari besi atau baja, sedangkan kaleng aluminium tidak ikut tertarik.","Ketiganya tertarik, karena paku, klip, dan kaleng aluminium sama-sama logam yang selalu ditarik magnet.","Hanya kaleng aluminium yang tertarik, karena aluminium adalah logam paling ringan sehingga mudah terangkat.","Tidak ada yang tertarik, karena elektromagnet hanya dapat menarik benda yang sudah menjadi magnet sebelumnya."],"bahas":"Besi dan baja adalah bahan magnetik. Aluminium adalah logam nonmagnetik, sehingga tidak ditarik magnet."},{"ind":"evaluasi","soal":"Sari berkata, \"Pakai 4 baterai dan 300 lilitan, pasti paling kuat dan paling baik.\" Penilaian yang paling tepat adalah …","opsi":["Belum tentu: elektromagnet mungkin kuat, tetapi arus besar membuat kawat panas dan baterai cepat habis, jadi perlu diuji.","Tepat: elektromagnet yang paling kuat selalu merupakan rancangan terbaik, sehingga kriteria lain tidak penting.","Tepat: menambah baterai dan lilitan tidak pernah menimbulkan masalah, sehingga makin banyak makin baik.","Kurang tepat: menambah baterai justru memperlemah elektromagnet, karena arus yang besar merusak medan magnet."],"bahas":"Rancangan terbaik memenuhi semua kriteria: kuat, dapat melepas paku, tidak kepanasan, dan baterainya awet."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa paku besi lunak cocok sebagai inti derek pemilah sampah adalah …","opsi":["Besi lunak mudah menjadi magnet saat dialiri arus dan mudah kehilangan kemagnetannya kembali.","Besi lunak tidak pernah menjadi magnet, sehingga paku yang diangkat tidak akan menempel terlalu kuat pada inti.","Besi lunak menghasilkan listrik sendiri, sehingga derek tetap bekerja walaupun baterainya hampir habis.","Besi lunak lebih berat daripada baja, sehingga paku yang diangkat tertekan dan tidak mudah terjatuh."],"bahas":"Derek pemilah harus bisa mengangkat lalu melepas. Besi lunak memperkuat medan saat arus mengalir dan kehilangan kemagnetan saat arus diputus."},{"ind":"regulasi","soal":"Derekmu mengangkat 20 paku, tetapi kamu belum mengukur panas kawat dan lama baterai. Langkah yang paling tepat adalah …","opsi":["Mengukur panas kawat dan lama baterai lebih dulu, karena rancangan harus memenuhi semua kriteria yang ada.","Langsung menyimpulkan rancangan berhasil, karena kriteria terpenting derek hanyalah jumlah paku yang terangkat.","Menambah lilitan lagi agar derek mengangkat lebih banyak paku, tanpa memeriksa kriteria yang lainnya.","Menganggap kawat pasti aman, karena kawat tembaga tidak pernah menjadi panas walaupun dialiri arus besar."],"bahas":"Memeriksa kriteria yang belum diuji sebelum menyimpulkan adalah bagian dari regulasi diri."}],"B":[{"ind":"interpretasi","soal":"Data uji 100 lilitan: tanpa inti → 1 paku; inti aluminium → 1 paku; inti paku besi → 13 paku; inti baut baja → 9 paku (4 paku tertahan saat dimatikan). Makna data yang tepat adalah …","opsi":["Inti besi paling memperkuat magnet dan melepas paku; baja juga memperkuat tetapi menahan paku saat dimatikan.","Inti aluminium memperkuat elektromagnet sama baiknya dengan besi, karena keduanya sama-sama terbuat dari logam.","Jenis inti tidak berpengaruh, karena perbedaan jumlah paku hanya disebabkan oleh ukuran paku yang berbeda-beda.","Inti baja paling baik, karena paku yang tertahan saat dimatikan menunjukkan elektromagnet yang paling kuat."],"bahas":"Aluminium sama dengan tanpa inti (1 paku), karena nonmagnetik. Besi paling kuat dan melepas paku; baja menyisakan kemagnetan."},{"ind":"analisis","soal":"Kawat tipis 0,3 mm dan kawat tebal 0,6 mm sama-sama dililit 200 kali dengan baterai yang sama. Elektromagnet berkawat tebal lebih kuat. Penjelasan yang paling tepat adalah …","opsi":["Kawat tebal hambatannya lebih kecil, sehingga arus yang mengalir lebih besar dan medan magnetnya menjadi lebih kuat.","Kawat tebal mengandung lebih banyak magnet di dalamnya, sehingga medan magnetnya lebih kuat daripada kawat tipis.","Kawat tebal lebih berat, dan elektromagnet yang lebih berat selalu dapat mengangkat paku lebih banyak.","Kawat tipis memiliki hambatan lebih kecil, sehingga arusnya terlalu besar dan medan magnetnya menjadi rusak."],"bahas":"Kawat yang lebih tebal berhambatan lebih kecil. Dengan tegangan sama, arusnya lebih besar sehingga elektromagnet lebih kuat."},{"ind":"inferensi","soal":"Kutub utara sebuah elektromagnet didekatkan ke kutub utara magnet batang yang digantung. Dugaan yang paling masuk akal adalah …","opsi":["Magnet batang menjauh, karena kutub yang sejenis saling tolak-menolak seperti magnet tetap.","Magnet batang mendekat, karena elektromagnet selalu menarik magnet apa pun tanpa memperhatikan kutubnya.","Magnet batang diam saja, karena elektromagnet tidak memiliki kutub utara dan kutub selatan seperti magnet.","Magnet batang mendekat, karena kutub sejenis saling tarik-menarik bila salah satunya adalah elektromagnet."],"bahas":"Elektromagnet memiliki kutub utara dan selatan seperti magnet tetap. Kutub sejenis tolak-menolak."},{"ind":"evaluasi","soal":"Kelompok Bima mengklaim dereknya terbaik karena mengangkat 30 paku, tetapi kawatnya panas 5 W. Penilaian yang paling tepat adalah …","opsi":["Belum terbaik: dereknya sangat kuat, tetapi panas 5 W melebihi batas 3 W sehingga kawat berisiko panas.","Tepat: jumlah paku yang terangkat adalah satu-satunya ukuran derek terbaik, sehingga panas tidak penting.","Tepat: kawat yang panas menunjukkan arus besar, dan arus besar selalu tanda derek bekerja dengan baik.","Kurang tepat: derek dari baterai AA tidak mungkin mengangkat 30 paku, jadi data kelompok Bima pasti salah."],"bahas":"Kawat yang terlalu panas berbahaya dan menguras baterai. Rancangan terbaik memenuhi semua kriteria, termasuk panas ≤ 3 W."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa kumparan berarus listrik dapat menarik paku adalah …","opsi":["Arus listrik pada kawat menimbulkan medan magnet; lilitan memperkuatnya, dan inti besi memusatkannya.","Arus listrik membuat kawat menjadi lengket, sehingga paku menempel pada kawat seperti menempel pada lem.","Arus listrik mengalir ke dalam paku dan membuat paku tertarik oleh baterai melalui kawat tembaga.","Kawat tembaga adalah magnet alami, dan arus listrik hanya berfungsi membangunkan magnet di dalam kawat."],"bahas":"Oersted menemukan bahwa arus listrik menimbulkan medan magnet. Kumparan menjumlahkan medan dari setiap lilitan, dan inti besi memperkuatnya."},{"ind":"regulasi","soal":"Kamu mengganti inti, jumlah lilitan, dan jumlah baterai sekaligus, lalu derek menjadi lebih kuat. Sikap yang paling tepat adalah …","opsi":["Menyadari penyebabnya belum jelas, lalu menguji ulang dengan mengubah satu faktor saja untuk melihat pengaruhnya.","Menyimpulkan bahwa inti baru adalah penyebabnya, karena inti adalah bagian elektromagnet yang paling penting.","Menyimpulkan bahwa ketiga faktor sama kuat pengaruhnya, karena hasilnya membaik setelah ketiganya diubah.","Tidak perlu mencari penyebabnya, karena yang penting derek baru sudah lebih kuat daripada derek lama."],"bahas":"Mengubah tiga faktor sekaligus membuat penyebab perubahan tidak dapat dipastikan. Uji adil mengubah satu faktor pada satu waktu."}]},"pesawat":{"tujuan":["Menghitung keuntungan mekanis tuas dan katrol serta gaya kuasa yang dibutuhkan.","Menjelaskan bahwa pesawat sederhana memperkecil gaya tetapi tidak mengurangi usaha (gaya ditukar jarak).","Memilih dan merancang pesawat sederhana yang memenuhi batas gaya, jarak, dan biaya berdasarkan data."],"A":[{"ind":"interpretasi","soal":"Data uji karung 60 kg (berat 588 N), katrol licin: katrol tetap → gaya 588 N, tarik 0,5 m; katrol bebas → 294 N, 1 m; takal 4 katrol → 147 N, 2 m. Makna data yang tepat adalah …","opsi":["Makin besar keuntungan mekanis, makin kecil gaya yang dibutuhkan, tetapi jarak tariknya bertambah sebanding.","Makin banyak katrol, makin kecil gaya dan makin pendek jarak tarik, sehingga takal selalu paling menghemat tenaga.","Katrol tetap paling baik, karena jarak tariknya paling pendek sehingga usaha yang dikeluarkan juga paling kecil.","Jumlah katrol tidak berpengaruh, karena gaya yang dibutuhkan hanya ditentukan oleh massa karung yang diangkat."],"bahas":"Gaya × jarak selalu 294 J (588 × 0,5 = 294 × 1 = 147 × 2). Gaya mengecil, jarak membesar, usahanya tetap."},{"ind":"analisis","soal":"Takal 4 katrol yang sama diuji dua kali. Saat berkarat, gaya kuasa 210 N; setelah dibersihkan dan dilumasi, gaya kuasa 160 N. Penyebab paling tepat adalah …","opsi":["Gesekan pada katrol berkarat menambah gaya yang harus dikeluarkan, sehingga keuntungan mekanis nyata lebih kecil.","Pelumas menambah jumlah tali yang menopang beban, sehingga keuntungan mekanis takal itu menjadi lebih besar.","Karat membuat karung terasa lebih berat, karena karat menambah massa karung yang tergantung pada takal.","Katrol yang dilumasi berputar lebih cepat, sehingga karung naik lebih cepat dan gayanya berkurang dengan sendirinya."],"bahas":"Jumlah tali tidak berubah, jadi KM ideal tetap 4. Gesekan karat menurunkan KM nyata dari 588 ÷ 160 ≈ 3,7 menjadi 588 ÷ 210 = 2,8."},{"ind":"inferensi","soal":"Tuas sepanjang 2 m dipakai dengan lengan beban 0,5 m, sehingga lengan kuasanya 1,5 m. Dugaan gaya kuasa yang paling masuk akal untuk karung 588 N adalah …","opsi":["Sekitar 196 N, karena keuntungan mekanisnya 1,5 ÷ 0,5 = 3, sehingga gaya kuasa hanya sepertiga berat karung.","Sekitar 1.764 N, karena gaya kuasa sama dengan berat karung dikalikan perbandingan lengan kuasa dan lengan beban.","Sekitar 588 N, karena tuas hanya mengubah arah gaya dan sama sekali tidak dapat memperkecil gaya yang diperlukan.","Sekitar 294 N, karena tuas selalu memperkecil gaya tepat menjadi setengahnya, berapa pun panjang tuasnya."],"bahas":"Beban × lengan beban = kuasa × lengan kuasa: 588 × 0,5 = F × 1,5, sehingga F = 196 N."},{"ind":"evaluasi","soal":"Pak Darto berkata, \"Takal ini ajaib, karena kerja saya mengangkat karung jadi berkurang empat kali.\" Penilaian yang paling tepat adalah …","opsi":["Kurang tepat: gayanya memang berkurang empat kali, tetapi jarak tariknya empat kali lebih jauh, jadi usahanya tidak berkurang.","Tepat: takal mengurangi gaya dan usaha sekaligus, sehingga Pak Darto benar-benar bekerja empat kali lebih ringan.","Tepat: usaha hanya bergantung pada gaya yang dikeluarkan, sehingga gaya yang lebih kecil berarti usaha lebih kecil.","Kurang tepat: takal justru menambah gaya yang dibutuhkan, karena tali yang lebih panjang membuat karung lebih berat."],"bahas":"Usaha = gaya × jarak. Pesawat sederhana menukar gaya dengan jarak; usahanya tetap, bahkan bertambah sedikit karena gesekan."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa katrol bebas memperkecil gaya menjadi kira-kira setengahnya adalah …","opsi":["Beban ditopang dua bagian tali, sehingga tiap bagian tali cukup menahan setengah berat beban.","Katrol bebas mengurangi massa beban menjadi setengahnya, sehingga beban yang ditarik terasa jauh lebih ringan.","Katrol bebas berputar dua kali lebih cepat, sehingga tenaga putarannya membantu menarik beban ke atas.","Katrol bebas mengubah arah gaya ke bawah, dan menarik ke bawah selalu membutuhkan setengah gaya menarik ke atas."],"bahas":"Katrol bebas bergerak bersama beban dan ditopang dua bagian tali (KM = 2). Massa beban tidak berubah."},{"ind":"regulasi","soal":"Rancanganmu memenuhi batas gaya 200 N, tetapi kamu belum menghitung jarak tarik dan biaya. Langkah yang paling tepat adalah …","opsi":["Menghitung jarak tarik dan biaya terlebih dulu, karena rancangan harus memenuhi semua kriteria dan kendala.","Langsung menyimpulkan rancangan berhasil, karena kriteria terpenting pesawat sederhana hanyalah gaya yang kecil.","Menambah katrol lagi agar gaya makin kecil, tanpa memeriksa jarak tarik dan biaya yang harus dikeluarkan.","Menganggap jarak tarik pasti memenuhi, karena jarak tarik tidak pernah berubah walau jumlah katrol ditambah."],"bahas":"Gaya yang kecil dibayar dengan jarak yang jauh. Jarak tarik paling jauh 3 m dan biaya Rp 150.000 juga harus dicek."}],"B":[{"ind":"interpretasi","soal":"Data uji tuas (panjang 2 m) untuk karung 588 N: lengan beban 0,8 m → gaya 392 N; 0,5 m → 196 N; 0,4 m → 147 N; 0,2 m → 65 N. Batas gaya 200 N. Makna data yang tepat adalah …","opsi":["Makin pendek lengan beban, makin kecil gaya kuasa; lengan beban 0,5 m atau kurang sudah memenuhi batas 200 N.","Makin panjang lengan beban, makin kecil gaya kuasa, sehingga lengan beban 0,8 m adalah pilihan yang paling ringan.","Panjang lengan beban tidak berpengaruh, karena gaya kuasa hanya ditentukan oleh panjang tuas secara keseluruhan.","Gaya kuasa turun tepat 49 N setiap lengan beban dipendekkan 0,1 m, sehingga gaya pada 0,1 m pasti 0 N."],"bahas":"Dengan panjang tuas tetap, lengan beban yang pendek membuat lengan kuasa panjang dan KM besar. Penurunan gayanya tidak tetap."},{"ind":"analisis","soal":"Kelompok A dan B sama-sama memakai takal 4 katrol yang licin. Kelompok A memakai katrol besi berat, kelompok B katrol plastik ringan. Gaya kelompok A sedikit lebih besar. Penjelasan yang paling tepat adalah …","opsi":["Katrol bebas yang berat ikut terangkat bersama karung, sehingga beban total yang ditarik kelompok A menjadi lebih besar.","Katrol besi mengurangi jumlah tali yang menopang beban, sehingga keuntungan mekanis takal kelompok A menjadi kecil.","Katrol plastik menambah keuntungan mekanis, karena plastik lebih licin sehingga talinya terasa lebih pendek.","Katrol besi membuat karung naik lebih tinggi, sehingga kelompok A membutuhkan gaya tambahan untuk mengangkatnya."],"bahas":"Berat katrol bebas ikut diangkat. Itu sebabnya gaya nyata sedikit lebih besar daripada perhitungan ideal."},{"ind":"inferensi","soal":"Petani ingin memakai takal 6 katrol supaya gayanya hanya sekitar 100 N untuk menaikkan karung setinggi 0,5 m. Dugaan yang paling masuk akal adalah …","opsi":["Gaya kecil, tetapi tali harus ditarik sekitar 3 m, tepat di batas jarak tarik dan gesekannya bertambah.","Gaya menjadi kecil dan jarak tarik tetap 0,5 m, karena takal hanya mengubah gaya, bukan jarak tarik tali.","Gaya justru bertambah besar, karena makin banyak katrol selalu membuat beban menjadi makin berat ditarik.","Gaya menjadi nol, karena enam katrol cukup untuk menahan seluruh berat karung tanpa perlu ditarik petani."],"bahas":"KM 6 berarti jarak tarik 6 × 0,5 m = 3 m. Makin banyak katrol juga berarti gesekan dan berat katrol bertambah."},{"ind":"evaluasi","soal":"Kelompok Nina memilih katrol tetap dengan alasan \"paling mudah karena menarik ke bawah\". Gaya yang dibutuhkan 588 N. Penilaian yang paling tepat adalah …","opsi":["Belum memenuhi: katrol tetap hanya memudahkan arah tarikan, tetapi gayanya 588 N jauh melebihi batas gaya 200 N.","Tepat: menarik ke bawah selalu lebih ringan, sehingga katrol tetap sudah memenuhi kriteria gaya paling besar 200 N.","Tepat: katrol tetap memiliki keuntungan mekanis terbesar, karena katrolnya tidak ikut bergerak bersama karung.","Kurang tepat: katrol tetap tidak dapat dipakai untuk mengangkat beban, karena katrolnya tidak dapat berputar."],"bahas":"Katrol tetap KM = 1, hanya mengubah arah gaya. Kemudahan arah tarikan tidak mengubah besar gaya."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa efisiensi takal nyata selalu kurang dari 100% adalah …","opsi":["Sebagian usaha dipakai melawan gesekan dan mengangkat katrol bebas, jadi usaha keluar lebih dari usaha beban.","Sebagian usaha hilang lenyap begitu saja di dalam tali, karena energi dapat musnah saat tali sedang ditarik.","Takal menyimpan sebagian usaha sebagai cadangan, sehingga usaha itu baru keluar saat karung diturunkan kembali.","Karung menolak sebagian usaha yang diberikan, sehingga hanya setengah usaha yang benar-benar menaikkan karung."],"bahas":"Efisiensi = usaha untuk beban ÷ usaha dikeluarkan × 100%. Gesekan dan berat katrol membuat usaha dikeluarkan lebih besar."},{"ind":"regulasi","soal":"Kamu menghitung gaya ideal takal 147 N, tetapi saat diuji gaya yang terukur 200 N. Sikap yang paling tepat adalah …","opsi":["Mencari faktor nyata yang belum dihitung, seperti gesekan dan berat katrol, lalu memperbaikinya dan menguji ulang.","Menyimpulkan bahwa rumus keuntungan mekanis salah, sehingga perhitungan tidak perlu dipakai dalam merancang lagi.","Menuliskan 147 N di laporan, karena hasil perhitungan ideal lebih dapat dipercaya daripada hasil pengukuran.","Menyalahkan alat ukur tanpa memeriksa apa pun, karena perhitunganmu sudah pasti benar sejak awal perancangan."],"bahas":"Perhitungan ideal mengabaikan gesekan dan berat katrol. Selisih dengan hasil nyata menjadi petunjuk perbaikan."}]},"optik":{"tujuan":["Membedakan bayangan nyata dan maya serta sifat bayangan pada cermin dan lensa.","Menggunakan persamaan 1/f = 1/s + 1/s' dan perbesaran untuk mengatur jarak benda dan layar.","Merancang proyektor yang menghasilkan gambar besar, tajam, terang, dan tegak berdasarkan data."],"A":[{"ind":"interpretasi","soal":"Data uji lensa cembung f = 10 cm: HP 11 cm → bayangan 110 cm, lebar 10×; HP 15 cm → 30 cm, 2×; HP 30 cm → 15 cm, 0,5×. Makna data yang tepat adalah …","opsi":["Makin dekat HP ke titik fokus (tetapi di luarnya), makin jauh dan makin besar bayangannya.","Makin jauh HP dari lensa, makin besar bayangannya, sehingga HP sebaiknya diletakkan sejauh mungkin dari lensa.","Jarak HP tidak berpengaruh, karena besar bayangan hanya ditentukan oleh jarak fokus lensa yang dipakai.","Bayangan selalu 10 kali lebih besar daripada HP, berapa pun jarak HP ke lensa selama lensanya cembung."],"bahas":"Benda yang sedikit di luar fokus menghasilkan bayangan jauh dan sangat diperbesar. Inilah prinsip proyektor."},{"ind":"analisis","soal":"Kelompok A memakai lensa cekung dan tidak ada gambar di dinding; kelompok B memakai lensa cembung dan gambar muncul. Penyebab paling tepat adalah …","opsi":["Lensa cekung menyebarkan cahaya sehingga bayangannya maya, sedangkan lensa cembung membentuk bayangan nyata.","Lensa cekung terlalu gelap untuk dilewati cahaya HP, sehingga tidak ada cahaya yang sampai ke dinding kelas.","Lensa cekung membalik gambar dua kali, sehingga gambar di dinding hilang karena kedua bayangan saling menghapus.","Lensa cekung memiliki jarak fokus terlalu panjang, sehingga gambarnya terbentuk di luar ruangan kelas."],"bahas":"Bayangan maya tidak dapat ditangkap layar. Lensa cekung selalu membentuk bayangan maya, tegak, dan diperkecil."},{"ind":"inferensi","soal":"Gambar di dinding sudah tajam dan besar, tetapi terbalik. Dugaan perbaikan yang paling masuk akal adalah …","opsi":["Memutar HP 180° di kotak, karena lensa cembung membalik bayangan nyata sehingga gambar kembali tegak.","Mengganti lensa cembung dengan lensa cekung, karena lensa cekung membentuk bayangan tegak di dinding kelas.","Menjauhkan dinding dari lensa, karena gambar yang terbalik akan berbalik sendiri bila jaraknya cukup jauh.","Memperbesar diameter lensa, karena lensa yang lebar membuat gambar menjadi tegak dan lebih terang."],"bahas":"Bayangan nyata dari lensa cembung selalu terbalik. Bila HP sudah dibalik, bayangannya menjadi tegak."},{"ind":"evaluasi","soal":"Dewi berkata, \"Pakai cermin rias cekung saja, karena cermin rias juga bisa membesarkan wajah.\" Penilaian yang paling tepat adalah …","opsi":["Belum tentu: saat merias, wajah ada di dalam fokus sehingga bayangannya maya; proyektor butuh bayangan nyata.","Tepat: cermin cekung selalu membentuk bayangan nyata dan besar, berapa pun jarak benda ke cerminnya.","Tepat: semua alat yang dapat membesarkan bayangan pasti dapat dipakai untuk membuat proyektor sederhana.","Kurang tepat: cermin cekung tidak pernah dapat membentuk bayangan nyata, sehingga tidak berguna sama sekali."],"bahas":"Cermin cekung bisa membentuk bayangan nyata bila benda di luar fokus. Bayangan saat merias adalah maya, jadi alasannya belum tepat."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa gambar makin redup saat dinding dijauhkan agar gambar makin besar adalah …","opsi":["Cahaya terkumpul sama banyak, tetapi tersebar ke bidang gambar lebih luas, jadi tiap bagian redup.","Cahaya melemah karena lelah merambat jauh, sehingga cahaya yang sampai ke dinding kehilangan sebagian energinya.","Dinding yang jauh menyerap lebih banyak cahaya, karena dinding yang jauh selalu berwarna lebih gelap.","Lensa memancarkan cahaya lebih sedikit bila dinding jauh, karena lensa mengatur kecerahan sesuai jarak layar."],"bahas":"Jumlah cahaya yang terkumpul tetap. Luas gambar naik sebanding kuadrat lebarnya, sehingga kecerahan per bagian turun."},{"ind":"regulasi","soal":"Gambar proyektormu masih buram, lalu kamu menggeser HP, mengganti lensa, dan memindah kotak sekaligus. Langkah yang lebih tepat adalah …","opsi":["Mengatur satu hal saja, misalnya jarak HP ke lensa, sambil mengamati ketajaman sampai gambarnya paling jelas.","Terus mengubah ketiganya sekaligus sampai gambar tajam, karena cara itu paling cepat menemukan pengaturan.","Menerima gambar yang buram, karena proyektor dari kardus memang tidak akan pernah dapat menghasilkan gambar tajam.","Mengganti semua bahan dengan bahan baru, karena gambar buram pasti disebabkan oleh bahan yang sudah rusak."],"bahas":"Ketajaman bergantung pada kecocokan jarak benda dan jarak layar. Mengubah satu hal pada satu waktu membuat penyebabnya terlihat."}],"B":[{"ind":"interpretasi","soal":"Data uji HP 12 cm dari lensa cembung f = 10 cm (bayangan tajam di 60 cm): diameter 3 cm → kecerahan 25; 5 cm → 60; 8 cm → 150. Syarat kecerahan ≥ 40. Makna data yang tepat adalah …","opsi":["Lensa yang lebih lebar mengumpulkan lebih banyak cahaya; diameter 5 cm atau lebih sudah memenuhi syarat.","Diameter lensa tidak berpengaruh pada kecerahan, karena kecerahan hanya bergantung pada terangnya layar HP.","Lensa yang lebih lebar membuat gambar makin redup, karena cahayanya disebar ke bidang yang makin luas.","Kecerahan naik tepat sebanding diameter, sehingga lensa 10 cm pasti memberi kecerahan tepat sebesar 200."],"bahas":"Cahaya yang terkumpul sebanding luas lensa (kuadrat diameter), sehingga kenaikannya lebih cepat daripada diameter."},{"ind":"analisis","soal":"Lensa cembung f = 10 cm, HP 12 cm dari lensa. Bayangan tajam di 60 cm, tetapi dinding dipasang di 100 cm. Penyebab gambar buram adalah …","opsi":["Dinding tidak berada di jarak bayangan, sehingga sinar-sinar sudah menyebar lagi sebelum sampai ke dinding.","Dinding terlalu jauh dari HP, sehingga cahaya HP habis di perjalanan sebelum sempat membentuk gambar.","Jarak fokus lensa berubah bila dinding dijauhkan, sehingga lensa tidak lagi membentuk bayangan nyata.","Gambar menjadi maya bila dinding dijauhkan, karena bayangan nyata hanya terbentuk di dekat lensa saja."],"bahas":"1/10 = 1/12 + 1/s' menghasilkan s' = 60 cm. Gambar hanya tajam bila dinding berada pada jarak bayangan itu."},{"ind":"inferensi","soal":"Kamu ingin gambar lebih besar, sehingga dinding dijauhkan dari 60 cm menjadi 200 cm. Dugaan penyesuaian jarak HP yang paling masuk akal adalah …","opsi":["HP harus digeser lebih dekat ke titik fokus, agar bayangan terbentuk tepat di dinding yang lebih jauh.","HP harus digeser lebih jauh dari lensa, karena bayangan yang jauh selalu membutuhkan benda yang jauh pula.","HP tidak perlu digeser, karena gambar tetap tajam di jarak berapa pun selama lensanya tetap lensa cembung.","HP harus digeser ke dalam titik fokus, karena hanya di dalam fokus bayangan dapat diperbesar lebih jauh."],"bahas":"Untuk s' = 200 cm dan f = 10 cm, s ≈ 10,5 cm. Benda makin dekat ke fokus membuat bayangan makin jauh dan besar."},{"ind":"evaluasi","soal":"Kelompok Fajar mengklaim, \"Proyektor kami terbaik, gambarnya 150 cm!\" Ternyata kecerahannya hanya 15. Penilaian yang paling tepat adalah …","opsi":["Belum terbaik: gambarnya besar, tetapi kecerahan 15 di bawah syarat 40, sehingga gambarnya sulit dilihat.","Tepat: gambar yang paling besar selalu merupakan proyektor terbaik, sehingga kecerahan tidak perlu dihitung.","Tepat: gambar yang besar pasti juga terang, karena cahaya HP ikut membesar bersama gambar di dinding.","Kurang tepat: lensa sederhana tidak mungkin membuat gambar 150 cm, sehingga pengukuran kelompok itu salah."],"bahas":"Semua kriteria harus dipenuhi. Gambar yang makin besar justru makin redup karena cahayanya tersebar."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa bayangan nyata dapat ditangkap dinding tetapi bayangan maya tidak adalah …","opsi":["Bayangan nyata terbentuk dari sinar asli yang berpotongan, sedangkan bayangan maya dari perpanjangan sinar.","Bayangan nyata lebih terang daripada bayangan maya, sehingga hanya bayangan nyata yang terlihat di dinding.","Bayangan maya terbentuk di belakang mata kita, sehingga bayangan itu tidak dapat mencapai dinding kelas.","Bayangan nyata selalu lebih besar daripada bayangan maya, sehingga hanya bayangan nyata yang menutupi dinding."],"bahas":"Dinding hanya dapat menampilkan cahaya yang benar-benar sampai kepadanya, yaitu sinar yang berkumpul pada bayangan nyata."},{"ind":"regulasi","soal":"Simulasimu menunjukkan gambar tajam, tetapi proyektor kardus nyatanya sedikit buram di tepi. Sikap yang paling tepat adalah …","opsi":["Mencari faktor nyata yang tidak dihitung simulasi, misalnya mutu lensa atau posisi miring, lalu memperbaikinya.","Menyimpulkan bahwa simulasi pasti salah, sehingga hasil simulasi tidak perlu dipakai lagi dalam merancang.","Melaporkan hasil simulasi saja, karena hasil simulasi lebih bagus daripada hasil pengamatan proyektor nyata.","Menyimpulkan bahwa proyektor nyata pasti gagal, lalu berhenti tanpa mencari penyebab perbedaannya."],"bahas":"Simulasi menyederhanakan kenyataan. Perbedaan hasil menjadi petunjuk faktor yang belum diperhitungkan."}]},"bunyi":{"tujuan":["Membedakan frekuensi (tinggi nada) dan amplitudo (kenyaringan) pada getaran dan bunyi.","Menerapkan Hukum Mersenne untuk menjelaskan pengaruh panjang, tegangan, dan jenis senar terhadap frekuensi.","Merancang alat musik petik yang tepat nada, nyaring, dan aman berdasarkan data uji."],"A":[{"ind":"interpretasi","soal":"Data uji senar nilon dengan beban sama: panjang 60 cm → 220 Hz; 40 cm → 330 Hz; 30 cm → 440 Hz. Makna data yang tepat adalah …","opsi":["Makin pendek senar, makin tinggi frekuensinya; senar setengah panjang bergetar dua kali lipat.","Makin panjang senar, makin tinggi frekuensinya, sehingga senar 60 cm menghasilkan nada yang paling tinggi.","Panjang senar tidak berpengaruh, karena frekuensi hanya ditentukan oleh kuat lemahnya senar dipetik.","Frekuensi turun tepat 110 Hz setiap senar diperpendek 10 cm, sehingga senar 20 cm pasti bernada 550 Hz."],"bahas":"Frekuensi berbanding terbalik dengan panjang senar: 60 cm → 220 Hz, 30 cm → 440 Hz. Penurunannya tidak tetap per 10 cm."},{"ind":"analisis","soal":"Senar yang sama dipetik pelan lalu dipetik kuat. Nadanya tetap 440 Hz, tetapi bunyinya lebih nyaring saat dipetik kuat. Penjelasan yang paling tepat adalah …","opsi":["Petikan kuat memperbesar amplitudo getaran, sedangkan frekuensinya tetap karena panjang dan tegangannya sama.","Petikan kuat memperbesar frekuensi getaran, tetapi telinga kita tidak dapat mendengar perubahan nada itu.","Petikan kuat membuat senar lebih tegang, sehingga bunyinya lebih nyaring tetapi nadanya justru menjadi turun.","Petikan kuat menambah panjang gelombang bunyi, sehingga bunyinya lebih nyaring tanpa mengubah amplitudonya."],"bahas":"Kenyaringan ditentukan amplitudo, tinggi nada ditentukan frekuensi. Frekuensi bergantung pada panjang, tegangan, dan jenis senar."},{"ind":"inferensi","soal":"Senar 40 cm bernada 330 Hz. Panjangnya tetap, lalu beban botol dijadikan empat kali lebih berat. Dugaan frekuensi yang paling masuk akal adalah …","opsi":["Sekitar 660 Hz, karena frekuensi sebanding akar tegangan, dan akar dari empat kali adalah dua kali.","Sekitar 1.320 Hz, karena frekuensi naik empat kali lipat bila tegangan senar juga naik empat kali lipat.","Tetap 330 Hz, karena beban botol hanya membuat senar lebih nyaring tanpa mengubah tinggi nadanya.","Sekitar 165 Hz, karena beban yang lebih berat membuat senar bergetar lebih lambat dan nadanya turun."],"bahas":"Hukum Mersenne: f ∝ √T. Tegangan 4 kali membuat frekuensi √4 = 2 kali, yaitu 660 Hz."},{"ind":"evaluasi","soal":"Galih berkata, \"Biar nadanya naik ke 440 Hz, tambah saja kotak resonansinya.\" Penilaian yang paling tepat adalah …","opsi":["Kurang tepat: kotak resonansi membuat bunyi lebih nyaring, tetapi tidak mengubah tinggi nada senar itu.","Tepat: kotak resonansi selalu menaikkan frekuensi senar, sehingga nada pasti naik mendekati 440 Hz.","Tepat: makin besar kotak resonansi, makin tinggi nada senar yang dihasilkan saat senar itu dipetik.","Kurang tepat: kotak resonansi justru menurunkan nada senar, sehingga nadanya makin menjauhi 440 Hz."],"bahas":"Resonansi memperkuat bunyi (kenyaringan). Tinggi nada tetap ditentukan panjang, tegangan, dan jenis senar."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap bagaimana bunyi senar sampai ke telinga penonton adalah …","opsi":["Senar menggetarkan udara, lalu getaran merambat sebagai gelombang longitudinal sampai ke gendang telinga.","Senar melemparkan partikel udara langsung dari panggung ke telinga penonton yang duduk di kursi paling belakang.","Bunyi merambat sebagai cahaya yang sangat cepat, sehingga penonton mendengar bunyi pada saat yang sama persis.","Senar mengirim bunyi melalui lantai panggung, karena bunyi tidak dapat merambat melalui udara sama sekali."],"bahas":"Partikel udara hanya bergetar maju-mundur di tempatnya dan meneruskan getaran ke partikel berikutnya. Yang merambat adalah gelombangnya."},{"ind":"regulasi","soal":"Senarmu sudah tepat 440 Hz, tetapi kenyaringannya baru 58 dB dan kamu ingin segera tampil. Langkah yang paling tepat adalah …","opsi":["Memperbaiki kenyaringan tanpa mengubah nada, misalnya menambah kotak resonansi, lalu mengukurnya ulang.","Menegangkan senar lebih kuat agar bunyinya lebih nyaring, tanpa memeriksa nada setelah perubahan itu.","Langsung tampil, karena syarat terpenting alat musik hanyalah nada yang tepat, bukan kenyaringan bunyinya.","Memperpendek senar agar bunyinya lebih nyaring, karena senar pendek selalu menghasilkan bunyi lebih keras."],"bahas":"Syarat kenyaringan ≥ 65 dB belum terpenuhi. Perubahan yang dipilih sebaiknya tidak merusak nada yang sudah tepat."}],"B":[{"ind":"interpretasi","soal":"Data uji senar 40 cm dengan beban sama: senar baja → 520 Hz; senar nilon → 330 Hz; karet gelang → 95 Hz. Makna data yang tepat adalah …","opsi":["Jenis senar memengaruhi frekuensi; senar yang lebih ringan per meter dan kaku menghasilkan nada lebih tinggi.","Jenis senar tidak berpengaruh, karena frekuensi hanya ditentukan oleh panjang senar dan beban yang menegangkan.","Karet gelang menghasilkan nada paling tinggi, karena karet paling lentur sehingga bergetar paling cepat.","Senar baja bernada paling tinggi karena paling berat, dan senar yang berat selalu bergetar paling cepat."],"bahas":"Hukum Mersenne: f ∝ 1/√μ. Senar baja tipis ringan per meter dan tidak meregang, sehingga nadanya tinggi."},{"ind":"analisis","soal":"Senar nilon bernada 440 Hz saat beban 2 kg. Setelah beberapa menit, nadanya turun menjadi 425 Hz walaupun beban tidak diubah. Penjelasan yang paling tepat adalah …","opsi":["Senar nilon sedikit meregang sehingga tegangannya berkurang, dan nada turun karena frekuensi bergantung pada tegangan.","Udara di ruangan menyerap sebagian frekuensi senar, sehingga nada senar terdengar lebih rendah setelah lama.","Kotak resonansi menjadi lelah karena terus bergetar, sehingga kotak itu menurunkan nada senar sedikit demi sedikit.","Senar nilon bertambah ringan setelah dipetik berkali-kali, sehingga nadanya turun dari 440 Hz menjadi 425 Hz."],"bahas":"Tegangan yang berkurang menurunkan frekuensi. Karena itu alat musik senar perlu disetel ulang secara berkala."},{"ind":"inferensi","soal":"Senar nilon 30 cm bernada 440 Hz. Kotak hanya muat senar sampai 60 cm, dan kamu ingin nada A rendah (220 Hz) tanpa mengganti beban. Dugaan paling masuk akal adalah …","opsi":["Senar dipanjangkan menjadi 60 cm, karena frekuensi berbanding terbalik dengan panjang senar.","Senar dipendekkan menjadi 15 cm, karena senar yang lebih pendek selalu menghasilkan nada yang lebih rendah.","Panjang senar dibiarkan tetap, lalu senar dipetik lebih pelan agar nadanya turun menjadi setengahnya.","Senar dipanjangkan menjadi 120 cm, karena frekuensi turun sebanding dengan kuadrat panjang senar itu."],"bahas":"f ∝ 1/L. Untuk frekuensi setengahnya, panjang senar dibuat dua kali, yaitu 60 cm, masih dalam batas kotak."},{"ind":"evaluasi","soal":"Kelompok Putu menegangkan senar baja dengan beban 10 kg agar \"pasti nyaring\", dan senarnya putus. Penilaian yang paling tepat adalah …","opsi":["Kurang tepat: tegangan menaikkan nada, bukan kenyaringan; beban berlebih membuat senar putus dan berbahaya.","Tepat: beban yang lebih berat selalu membuat bunyi lebih nyaring, dan senar putus hanya karena kebetulan semata.","Tepat: senar yang putus menunjukkan bunyinya sudah paling nyaring, sehingga rancangannya sudah berhasil.","Kurang tepat: beban tidak memengaruhi senar sama sekali, sehingga senar itu putus karena salah dipetik."],"bahas":"Kenyaringan ditentukan amplitudo dan resonansi. Tegangan berlebih menaikkan nada dan melanggar kriteria senar tidak putus."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa kotak kardus berlubang membuat bunyi senar lebih nyaring adalah …","opsi":["Kotak dan udara di dalamnya ikut bergetar dengan senar (resonansi), sehingga lebih banyak udara digetarkan.","Kotak menambah tegangan senar, sehingga senar bergetar lebih cepat dan bunyinya menjadi lebih nyaring.","Lubang kotak menyimpan bunyi senar untuk sementara, lalu melepaskannya sekaligus sehingga terdengar keras.","Kotak memantulkan seluruh bunyi ke arah pemain, sehingga pemain merasa bunyinya lebih nyaring dari biasanya."],"bahas":"Senar sendiri hanya menggetarkan sedikit udara. Kotak yang ikut bergetar menggetarkan udara jauh lebih banyak."},{"ind":"regulasi","soal":"Kamu memperkirakan senar 30 cm akan bernada 440 Hz, tetapi alat penyetel nada menunjukkan 410 Hz. Sikap yang paling tepat adalah …","opsi":["Memeriksa ulang anggapan dalam perkiraan, misalnya berat beban atau jenis senar, lalu menyetel dan mengukur ulang.","Menyimpulkan bahwa alat penyetel nada rusak, karena perkiraan yang dibuat dengan rumus pasti selalu benar.","Menuliskan 440 Hz di laporan, karena selisih 30 Hz terlalu kecil untuk didengar oleh penonton pentas.","Mengabaikan perkiraan pada uji berikutnya, karena membuat perkiraan sebelum menguji tidak ada gunanya."],"bahas":"Selisih 30 Hz jauh di atas batas 5 Hz. Membandingkan perkiraan dengan hasil membantu menemukan anggapan yang keliru."}]},"gempa":{"tujuan":["Menjelaskan penyebab gempa bumi dan perambatan gelombang seismik.","Menganalisis pengaruh frekuensi alami, resonansi, kekakuan, dan massa terhadap ayunan bangunan.","Merancang miniatur rumah tahan gempa dengan pengaku, sambungan, atap, dan fondasi yang tepat berdasarkan data."],"A":[{"ind":"interpretasi","soal":"Data uji meja getar 3 Hz: rumah frekuensi alami 1,5 Hz → penguatan 1,3×; 2,8 Hz → 6,5×; 6 Hz → 1,4×. Makna data yang tepat adalah …","opsi":["Ayunan paling diperkuat saat frekuensi alami rumah mendekati frekuensi guncangan 3 Hz, yaitu resonansi.","Makin tinggi frekuensi alami rumah, makin besar penguatan, sehingga rumah 6 Hz paling berbahaya saat diguncang.","Frekuensi alami tidak berpengaruh, karena penguatan hanya ditentukan oleh kuat lemahnya guncangan meja getar.","Makin rendah frekuensi alami rumah, makin besar penguatan, sehingga rumah 1,5 Hz paling berbahaya diguncang."],"bahas":"Penguatan terbesar (6,5×) terjadi pada 2,8 Hz yang dekat dengan 3 Hz. Itulah resonansi."},{"ind":"analisis","soal":"Dua rumah kardus identik diuji. Rumah P beratap genteng tiruan berat, rumah Q beratap seng ringan. Rumah P retak, rumah Q tidak. Penyebab paling tepat adalah …","opsi":["Gaya gempa sebanding dengan massa (F = m × a), sehingga atap berat menimbulkan gaya lebih besar di dinding.","Atap ringan membuat meja getar berguncang lebih pelan, sehingga rumah Q menerima guncangan yang lebih lemah.","Atap berat menambah kekuatan sambungan, sehingga rumah P seharusnya lebih kuat dan retaknya karena kebetulan.","Atap seng memantulkan getaran kembali ke meja, sehingga getaran tidak sempat masuk ke dinding rumah Q."],"bahas":"Percepatan guncangan sama, tetapi massa atap P lebih besar. Gaya yang harus ditahan dinding dan sambungan P lebih besar."},{"ind":"inferensi","soal":"Sebuah rumah berfrekuensi alami 2,5 Hz diberi pengaku sehingga sedikit lebih kaku dan frekuensinya naik ke 2,9 Hz. Meja getar berguncang 3 Hz. Dugaan yang paling masuk akal adalah …","opsi":["Ayunan bisa justru membesar, karena frekuensi alami rumah makin dekat ke 3 Hz sehingga resonansi menguat.","Ayunan pasti mengecil, karena rumah yang lebih kaku selalu lebih aman dari guncangan berapa pun frekuensinya.","Ayunan tidak berubah, karena pengaku hanya memperkuat sambungan tanpa mengubah frekuensi alami rumah.","Ayunan menjadi nol, karena rumah dengan pengaku sama sekali tidak dapat bergerak saat meja getar berguncang."],"bahas":"Sedikit lebih kaku menggeser frekuensi alami mendekati frekuensi guncangan. Menambah kekakuan harus cukup banyak agar menjauh."},{"ind":"evaluasi","soal":"Bayu berkata, \"Rumah kami pasti tahan gempa karena tidak runtuh saat diuji.\" Data menunjukkan simpangan antar-lantai 2,4%. Penilaian yang paling tepat adalah …","opsi":["Belum tentu: rumah memang tidak runtuh, tetapi simpangan 2,4% melebihi batas 1,5% sehingga dindingnya bisa retak.","Tepat: rumah yang tidak runtuh sudah pasti tahan gempa, sehingga simpangan antar-lantai tidak perlu diperiksa.","Tepat: simpangan yang besar menunjukkan rumah lentur, dan rumah lentur selalu merupakan rumah yang terbaik.","Kurang tepat: rumah kardus tidak mungkin tahan gempa, sehingga hasil uji kelompok Bayu pasti salah ukur."],"bahas":"Kriteria tahan gempa mencakup tidak runtuh, tidak retak (≤ 1,5%), dan tetap di fondasi. Semuanya harus dipenuhi."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap tentang penyebab gempa bumi tektonik adalah …","opsi":["Energi tersimpan di batuan saat lempeng bergeser lepas tiba-tiba dan merambat sebagai gelombang seismik.","Inti bumi yang sangat panas meledak sesekali, lalu ledakannya mendorong permukaan tanah naik turun dengan cepat.","Air laut yang pasang menekan dasar laut sangat kuat, sehingga daratan di sekitarnya ikut berguncang keras.","Bangunan yang terlalu berat menekan tanah, sehingga tanah di bawah kota besar bergetar dan menimbulkan gempa."],"bahas":"Lempeng tektonik terus bergerak. Batuan menahan tegangan sampai patah, lalu energinya dilepas sebagai gelombang seismik."},{"ind":"regulasi","soal":"Rumahmu lolos semua kriteria pada guncangan 2 cm, tetapi kamu belum mencoba guncangan lebih kuat. Sikap yang paling tepat adalah …","opsi":["Menguji pada guncangan yang lebih kuat guna melihat batas aman rumah, lalu mencatat bagian yang mulai rusak.","Berhenti menguji, karena rumah yang lolos pada 2 cm pasti juga lolos pada guncangan berapa pun kekuatannya.","Menambah semua pengaku yang ada sekaligus, agar rumah pasti lolos tanpa perlu diuji pada guncangan lain.","Melaporkan bahwa rumah tahan semua gempa, karena hasil uji pada satu guncangan sudah cukup untuk dasar klaim."],"bahas":"Mengetahui batas kemampuan rancangan membantu memahami bagian terlemah dan menghindari klaim yang berlebihan."}],"B":[{"ind":"interpretasi","soal":"Data uji rumah 2 lantai: tanpa pengaku → simpangan antar-lantai 3,1%; bresing silang → 1,2%; dinding geser → 0,9%. Batas 1,5%. Makna data yang tepat adalah …","opsi":["Pengaku mengurangi simpangan antar-lantai; bresing silang dan dinding geser sama-sama memenuhi batas 1,5%.","Hanya dinding geser yang memenuhi syarat, karena simpangan harus sekecil mungkin, bukan cukup di bawah batas.","Pengaku menambah simpangan antar-lantai, sehingga rumah tanpa pengaku justru paling aman dari keretakan.","Jenis pengaku tidak berpengaruh, karena perbedaan simpangan hanya disebabkan oleh ketelitian alat ukur."],"bahas":"Simpangan 1,2% dan 0,9% sama-sama di bawah 1,5%. Pilihan di antara keduanya dapat ditimbang dari biaya."},{"ind":"analisis","soal":"Rumah dengan bresing silang yang ditempel selotip tetap rusak, sedangkan rumah sama dengan sambungan lem + pasak utuh. Penyebab paling tepat adalah …","opsi":["Sambungan selotip lebih lemah sehingga lepas sebelum pengaku bekerja; gaya hanya tersalur bila sambungannya kuat.","Selotip menambah massa rumah, sehingga gaya gempa yang diterima rumah bersambungan selotip menjadi lebih besar.","Pasak tusuk sate menurunkan frekuensi guncangan meja getar, sehingga rumah bersambungan pasak lebih aman.","Lem membuat rumah lebih lentur, dan rumah yang lentur selalu tidak rusak walaupun pengakunya terlepas."],"bahas":"Pengaku hanya efektif bila sambungan mampu menyalurkan gaya. Sambungan adalah titik lemah yang sering gagal lebih dulu."},{"ind":"inferensi","soal":"Rumah diletakkan di atas bantalan karet sandal (isolasi dasar), sedangkan bangunan dan guncangan meja tetap sama. Dugaan yang paling masuk akal adalah …","opsi":["Getaran ke bangunan berkurang karena diredam bantalan lentur, tetapi geser di fondasi perlu dicek.","Getaran yang masuk bertambah besar, karena karet memantul-mantul dan menambah guncangan ke dalam bangunan.","Getaran tidak berubah, karena bantalan karet hanya berfungsi agar rumah tidak tergores oleh permukaan meja.","Getaran hilang sepenuhnya, sehingga rumah tidak lagi membutuhkan pengaku maupun sambungan yang kuat."],"bahas":"Isolasi dasar meredam guncangan sebelum masuk ke bangunan. Namun geser permanen di fondasi tetap harus ≤ 1 cm."},{"ind":"evaluasi","soal":"Kelompok Sinta mengklaim rumahnya terbaik karena memakai dinding geser, bresing, pasak, dan isolasi sekaligus, dengan biaya Rp 40.000. Penilaian yang paling tepat adalah …","opsi":["Belum terbaik: rumahnya mungkin sangat kuat, tetapi biaya Rp 40.000 melebihi batas Rp 25.000 bagi warga desa.","Tepat: rumah yang memakai semua penguat pasti terbaik, sehingga biaya pembuatan tidak perlu diperhatikan lagi.","Tepat: biaya yang mahal selalu menandakan rumah yang kuat, sehingga warga desa pasti memilih rancangan itu.","Kurang tepat: memakai semua penguat sekaligus membuat rumah pasti runtuh, karena rumah menjadi terlalu kaku."],"bahas":"Rancangan yang baik memenuhi kriteria sekaligus kendala. Biaya penting karena rumah warga harus terjangkau."},{"ind":"eksplanasi","soal":"Penjelasan yang paling lengkap mengapa bresing silang membuat dinding rumah lebih tahan guncangan adalah …","opsi":["Bresing membagi dinding jadi segitiga yang tidak mudah berubah bentuk, sehingga dinding lebih kaku dan kuat.","Bresing menambah berat dinding, sehingga dinding yang berat tertahan di tempatnya dan tidak ikut bergoyang.","Bresing menyerap seluruh energi gempa, sehingga energi itu tidak pernah sampai ke lantai dan atap rumah.","Bresing memperlambat getaran meja, sehingga frekuensi guncangan yang diterima rumah menjadi jauh lebih kecil."],"bahas":"Bingkai persegi mudah miring menjadi jajar genjang. Batang diagonal membentuk segitiga yang menahan perubahan bentuk."},{"ind":"regulasi","soal":"Kamu mengganti pengaku, atap, dan fondasi sekaligus, lalu rumah lolos uji. Saat ditanya bagian mana yang paling berpengaruh, kamu tidak tahu. Sikap yang paling tepat adalah …","opsi":["Menguji ulang dengan mengubah satu bagian pada satu waktu, agar pengaruh tiap bagian dapat diketahui dengan jelas.","Menjawab bahwa fondasi paling berpengaruh, karena fondasi adalah bagian rumah yang letaknya paling bawah.","Menyimpulkan bahwa ketiga bagian sama besar pengaruhnya, karena rumah baru lolos setelah ketiganya diubah.","Tidak perlu mencari tahu, karena yang terpenting rumah sudah lolos uji dan tidak perlu dijelaskan lagi."],"bahas":"Mengubah banyak hal sekaligus membuat penyebab keberhasilan tidak dapat dipastikan dan sulit diulang."}]}};
